// Üretilen dosya: tool/ozgun/uret.py. Sınav Hazırlık · Sözel ve sayısal akıl yürütme: takvim-saat, yön-rota, turnuva-puan, raf-koltuk dizilimi ve kurallı şifre kurguları (orta).
const ozExam19Orta = <(String, String, List<String>, String)>[
  ('Artık yılda 1 Ocak Çarşamba günü ise aynı yılın 1 Mart günü haftanın hangi gününe denk gelir?', 'Pazar', ['Cumartesi', 'Pazartesi', 'Perşembe'], 'Ocak 31 + Şubat 29 = 60 gün geçer. 60 = 8 × 7 + 4 olduğundan Çarşamba\'dan 4 gün ileri gidilir ve Pazar bulunur.'),
  ('Deniz\'in saati her gün 4 dakika ileri gidiyor. Saati Pazartesi günü öğle 12:00\'de doğru ayarladı. Aynı haftanın Cuma günü öğle 12:00\'de saati kaçı gösterir?', '12:16', ['12:12', '12:20', '12:08'], 'Pazartesi\'den Cuma\'ya 4 gün geçer. Saat 4 × 4 = 16 dakika ileri gider ve 12:16\'yı gösterir.'),
  ('Mutfak saati her saatte 3 dakika geri kalıyor. Saat Çarşamba 08:00\'de doğru ayarlandı. Perşembe günü gerçek saat 20:00 olduğunda bu saat kaçı gösterir?', '18:12', ['18:48', '19:12', '17:12'], '08:00\'den ertesi gün 20:00\'ye 36 saat geçer. Saat 36 × 3 = 108 dakika yani 1 saat 48 dakika geri kalır; 20:00 − 1:48 = 18:12 olur.'),
  ('Bir ayın 1\'i Cuma günü ve bu ay 30 gün çekiyor. Bu ayda kaç tane Pazar günü vardır?', '4', ['5', '3', '6'], 'Cuma 1, Cumartesi 2, Pazar 3 olur. Pazar günleri 3, 10, 17, 24 olur; bir sonraki 31 ay dışındadır. Toplam 4 Pazar vardır.'),
  ('İki fırından birincisi her 45 dakikada, ikincisi her 60 dakikada bir tezgâha sıcak ekmek çıkarıyor. İkisi sabah 06:00\'da birlikte ekmek çıkardıysa bir sonraki ortak çıkarma saat kaçta olur?', '09:00', ['08:30', '09:30', '10:00'], 'EKOK(45, 60) = 180 dakikadır. 180 dakika 3 saattir; 06:00 + 3 saat = 09:00 olur.'),
  ('Bir istasyondan banliyö treni her 18 dakikada, şehirlerarası otobüs her 24 dakikada bir kalkıyor. İkisi 07:10\'da birlikte kalktıysa tekrar birlikte kalkacakları saat kaçtır?', '08:22', ['08:10', '08:34', '08:12'], 'EKOK(18, 24) = 72 dakika yani 1 saat 12 dakikadır. 07:10 + 1:12 = 08:22 olur.'),
  ('A şehrinin yerel saati B şehrinden 6 saat ileridir. Bir uçak A şehrinden Cuma günü yerel saatle 03:00\'te kalkıp 4 saat uçarak B şehrine iniyor. B şehrinin yerel saati ve günü, iniş anında nedir?', 'Cuma 01:00', ['Cuma 13:00', 'Perşembe 21:00', 'Cuma 07:00'], 'Varış anında A şehrinde Cuma 07:00\'dir. B şehri 6 saat geride olduğundan B\'de saat Cuma 01:00\'dir.'),
  ('12 Mart günü Cuma ise aynı tarihten 100 gün sonrası haftanın hangi gününe denk gelir?', 'Pazar', ['Cumartesi', 'Pazartesi', 'Salı'], '100 = 14 × 7 + 2 olduğundan Cuma\'dan 2 gün ileri gidilir ve Pazar bulunur.'),
  ('Bir ayın ikinci Pazar günü ayın 9\'una denk geliyor ve bu ay 31 gün çekiyor. Bu ayın son Pazar günü kaçıncı gündür?', '30', ['29', '31', '28'], 'İkinci Pazar 9 ise Pazarlar 2, 9, 16, 23, 30 günleridir. Sonraki Pazar 37 olacağından ay dışında kalır; son Pazar 30\'dur.'),
  ('Bir kitap kulübü her 10 günde bir toplanıyor. İlk toplantı 5 Mart Çarşamba günü yapıldı. Mart ayı 31 gün olduğuna göre dördüncü toplantı hangi tarihe ve güne denk gelir?', '4 Nisan Cuma', ['4 Nisan Cumartesi', '5 Nisan Cumartesi', '3 Nisan Perşembe'], '4. toplantı ilkinden 3 × 10 = 30 gün sonradır. 5 Mart + 30 gün = 4 Nisan\'dır. 30 = 4 × 7 + 2 olduğundan Çarşamba\'dan iki gün ileri gidilir ve Cuma bulunur.'),
  ('Akrep 5 saat 40 dakikada kaç derece döner?', '170°', ['180°', '160°', '340°'], 'Akrep dakikada 0,5° döner. 5 saat 40 dakika 340 dakikadır; 340 × 0,5° = 170° bulunur.'),
  ('45 gün önce Salı günü olduysa bugün haftanın hangi günüdür?', 'Cuma', ['Çarşamba', 'Perşembe', 'Pazar'], '45 = 6 × 7 + 3 olduğundan Salı\'dan 3 gün ileri gidilir ve Cuma bulunur.'),
  ('Bir bisiklet yarışı 14:07:45\'te başlıyor ve 15:02:20\'de bitiyor. Yarış kaç dakika kaç saniye sürmüştür?', '54 dk 35 sn', ['55 dk 35 sn', '54 dk 25 sn', '55 dk 25 sn'], '14:07:45\'ten 15:07:45\'e 1 saat vardır. Bitişe 5 dk 25 sn kala olduğundan 60 dk − 5 dk 25 sn = 54 dk 35 sn bulunur.'),
  ('Bir ilaç hatırlatıcısı her 8 saatte bir çalıyor. İlk çalış Salı günü 06:00\'dadır. Onuncu çalış hangi gün ve saatte olur?', 'Cuma 06:00', ['Cuma 14:00', 'Perşembe 22:00', 'Cumartesi 06:00'], '10. çalışa kadar 9 aralık vardır. 9 × 8 = 72 saat yani tam 3 gündür; Salı 06:00 + 3 gün = Cuma 06:00 olur.'),
  ('Bir ayın 1\'i Çarşamba günü ve ay 31 gün çekiyor. Bu ayda hem Cumartesi hem Pazar günü ay içinde kalan kaç tam hafta sonu vardır?', '4', ['5', '3', '6'], 'Cumartesiler 4, 11, 18, 25; Pazarlar 5, 12, 19, 26 günleridir. 29, 30, 31 Çarşamba, Perşembe, Cuma olur. Tam hafta sonu sayısı 4\'tür.'),
  ('Okulun bahçe nöbeti Kerem\'e her 9 günde bir düşüyor ve ilk nöbet Pazartesi günüdür. Kerem\'in nöbetinin yeniden bir Pazartesi gününe denk gelmesi için ilk nöbetten itibaren en az kaç gün geçmelidir?', '63 gün', ['72 gün', '54 gün', '81 gün'], 'Geçen gün sayısı hem 9\'un hem 7\'nin katı olmalıdır. EKOK(9, 7) = 63 olduğundan 63 gün sonra yeniden Pazartesi olur.'),
  ('Bir yuvarlak masada 10 kişi eşit aralıklarla oturuyor ve koltuklar 1\'den 10\'a saat yönünde numaralandırılmıştır. Deniz 3 numaralı koltukta oturuyor. Tam karşısında kimin koltuğu vardır?', '8', ['7', '9', '10'], 'Eşit aralıklı 10 kişide karşılıklı koltuklar 5 numara farklıdır. 3 + 5 = 8 olur.'),
  ('Üç raflı bir dolapta Fizik, Kimya ve Biyoloji kitapları farklı raflara konmuştur. Fizik kitapları Kimya kitaplarının üstündedir ve Biyoloji kitapları en alt raftadır. Orta rafta hangi kitaplar vardır?', 'Kimya', ['Fizik', 'Biyoloji', 'Matematik'], 'Biyoloji en altta, Fizik Kimya\'nın üstünde olduğundan üstten alta sıra Fizik, Kimya, Biyoloji olur. Orta raf Kimya\'dır.'),
  ('Beş arkadaş (Ayşe, Bora, Ceren, Derya, Emre) yan yana 5 koltukta oturuyor. Ayşe en solda, Ceren tam ortada, Bora Ceren\'in hemen sağındadır. Emre 2. koltukta oturduğuna göre Derya kaçıncı koltuktadır?', '5. koltuk', ['2. koltuk', '4. koltuk', '1. koltuk'], 'Ayşe 1, Ceren 3, Bora 4. koltuktadır. Emre 2 olduğundan boşta kalan 5. koltukta Derya oturur.'),
  ('Bir rafta 8 kitap vardır. Matematik kitabı soldan 3. sıradadır ve Tarih kitabı Matematik\'in 4 sıra sağındadır. Tarih kitabı sağdan kaçıncı sıradadır?', '2', ['3', '1', '4'], 'Tarih soldan 3 + 4 = 7. sıradadır. Sağdan sıra 8 − 7 + 1 = 2 olur.'),
  ('Bir tiyatro salonunda her sırada 14 koltuk vardır. Koltuklar A sırasından başlayarak 1\'den itibaren numaralanmıştır (A: 1–14, B: 15–28, C: 29–42 ...). 50 numaralı koltuk hangi sırada ve o sırada kaçıncı koltuktur?', 'D sırası, 8. koltuk', ['C sırası, 8. koltuk', 'D sırası, 6. koltuk', 'E sırası, 8. koltuk'], 'A–C sıraları toplam 42 koltuktur. 50 − 42 = 8 olduğundan koltuk D sırasının 8. koltuğudur.'),
  ('Yuvarlak bir masada 8 kişi eşit aralıkla oturuyor. Fatih, Ece\'nin saat yönünde 2. kişisidir ve Gül, Fatih\'in tam karşısında oturmaktadır. Ece ile Gül arasındaki kısa yolda kaç kişi vardır?', '1 kişi', ['2 kişi', '3 kişi', '4 kişi'], 'Ece 0, Fatih 2, Gül 6 numaralı konumdadır. Ece\'den Gül\'e kısa yol 0 → 7 → 6 şeklindedir; arada yalnız 7 numaradaki kişi bulunur.'),
  ('Bir sinema salonunda 2 sıra, her sırada 3 koltuk vardır. Aslı ön sıranın ortasında oturuyor. Cem Aslı\'nın hemen arkasında, Barış Cem\'in hemen solunda, Defne ise Barış\'ın hemen önündedir. Defne, Aslı\'ya göre nerededir?', 'Aslı\'nın solunda', ['Aslı\'nın sağında', 'Aslı\'nın hemen arkasında', 'Cem\'in sağında'], 'Cem arka sıra ortada, Barış arka sıra solda oturur. Defne Barış\'ın önünde yani ön sıra solda, Aslı\'nın solundadır.'),
  ('Soldan sağa dizilen beş kitaptan Coğrafya en soldadır. Tarih, Felsefe\'den önce ama Mantık\'tan sonradır. Sosyoloji, Felsefe\'nin hemen sağındadır. Soldan 4. sırada hangi kitap vardır?', 'Felsefe', ['Sosyoloji', 'Coğrafya', 'Tarih'], 'Sıralama Coğrafya, Mantık, Tarih, Felsefe, Sosyoloji şeklindedir. 4. sırada Felsefe bulunur.'),
  ('Bir otobüste her sırada 4 koltuk (2+2 düzeni: cam, koridor | koridor, cam) vardır. Koltuklar ön sıradan başlayarak her sırada soldan sağa 1, 2, 3, 4 diye numaralanmıştır. 27 numaralı koltuk hangi sırada ve hangi konumdadır?', '7. sıra, koridor yanı (sağ taraf)', ['7. sıra, cam kenarı (sağ taraf)', '6. sıra, koridor yanı (sağ taraf)', '7. sıra, koridor yanı (sol taraf)'], 'Her sırada 4 koltuk olduğundan 25–28 numaralı koltuklar 7. sıradadır. 27 numara bu sırada 3. koltuktur; bu koltuk koridorun sağındaki koridor yanı koltuktur.'),
  ('Bir sınıfta 5 sıra ve her sırada 6 öğrenci vardır. Selin soldan 4. sütunda, önden 3. sıradadır. Taner, Selin\'in tam arkasında oturuyor. Taner hangi sırada ve sağdan kaçıncı sütundadır?', '4. sıra, sağdan 3. sütun', ['4. sıra, sağdan 4. sütun', '2. sıra, sağdan 3. sütun', '4. sıra, sağdan 2. sütun'], 'Taner Selin\'in arkasında olduğundan 4. sıra ve soldan 4. sütundadır. Sağdan sütun sırası 6 − 4 + 1 = 3 olur.'),
  ('Bir markette soldan sağa dört ürün dizilecektir: süt, yoğurt, peynir, ayran. Ayran en soldadır. Peynir, sütün hemen soluna konacaktır. Yoğurt en sağda olmayacaktır. Peynir soldan kaçıncı sıradadır?', '3. sırada', ['2. sırada', '4. sırada', '1. sırada'], 'Ayran 1. sıradadır. Peynir-süt ikilisi bitişik olup yoğurt 4. sırada olamayacağından düzen ayran, yoğurt, peynir, süt olur. Peynir 3. sıradadır.'),
  ('Üç çift (Aylin-Burak, Cansu-Deniz, Ece-Fırat) altı koltuğa yan yana oturuyor ve her çift birbirine bitişik oturuyor. Aylin en soldaki, Burak onun yanındaki koltuktadır. Ece-Fırat çifti en sağdadır ve Fırat en sağdaki koltukta değildir. Deniz, Burak\'ın yanında oturmadığına göre Deniz\'in hemen sağında kim oturur?', 'Fırat', ['Cansu', 'Ece', 'Burak'], 'Aylin 1, Burak 2, Ece 6, Fırat 5. koltuktadır. Cansu-Deniz 3 ve 4\'tedir; Deniz Burak\'ın yanında olamayacağından Deniz 4, Cansu 3\'tür. Deniz\'in sağındaki 5. koltukta Fırat vardır.'),
  ('Bir okul koridorunda dolaplar 1\'den başlayıp numaralanmıştır. Tek numaralı dolaplar sol duvarda, çift numaralılar sağ duvarda ve her tek numaranın karşısında ondan bir büyük çift sayı bulunur (1–2, 3–4, ...). 37 numaralı dolabın karşısında kaç numaralı dolap vardır?', '38', ['36', '39', '40'], '37 tek sayı olduğundan karşısında bir büyüğü, yani 38 numaralı dolap bulunur.'),
  ('Bir sinemanın A sırasında 10 koltuk vardır. Dört arkadaş yan yana oturacağına göre bu sırada seçilebilecek farklı ardışık dörtlü koltuk bloğu sayısı kaçtır?', '7', ['6', '8', '5'], 'Blok 1. koltuktan 7. koltuğa kadar başlayabilir. 10 − 4 + 1 = 7 olur.'),
  ('Bir kitap rafına 3 farklı roman ve 2 farklı şiir kitabı dizilecektir. Şiir kitapları yan yana olacağına göre kaç farklı dizilim vardır?', '48', ['24', '120', '96'], 'Şiir kitapları bir blok sayılırsa 4 öğe 4! = 24 şekilde dizilir. Blok içindeki iki kitap 2! = 2 şekilde dizildiğinden 24 × 2 = 48 olur.'),
  ('Dört arkadaş yan yana dört koltuğa oturacaktır. Seda en soldaki koltuğa oturmayacağına göre kaç farklı oturma düzeni vardır?', '18', ['6', '12', '24'], 'Toplam 4! = 24 düzen vardır. Seda en solda ise kalan 3 kişi 3! = 6 şekilde dizilir. 24 − 6 = 18 olur.'),
  ('Bir kütüphanede yan yana duran 14 kitap boyuna göre sıralanmıştır. Mert\'in kitabından daha uzun 5 kitap vardır. Mert\'in kitabından daha kısa kaç kitap vardır?', '8', ['9', '7', '5'], 'Toplam 14 kitaptan Mert\'in kitabı ve daha uzun 5 kitap çıkarılırsa 14 − 1 − 5 = 8 kitap kalır.'),
  ('Bir amfi tiyatronun ilk sırasında 10 koltuk vardır ve sonraki her sırada bir öncekinden 2 koltuk fazla bulunur. Tiyatro 15 sıradan oluştuğuna göre toplam koltuk sayısı kaçtır?', '360', ['380', '340', '330'], 'Sıralar 10, 12, ..., 38 olan aritmetik dizidir. Toplam 15 × (10 + 38) / 2 = 360 olur.'),
  ('Beş kitap renklerine göre boylarına dizilmiştir. Kırmızı, Mavi\'den kısa; Mavi, Yeşil\'den kısadır. Sarı, Yeşil\'den uzundur. Mor, Mavi\'den kısa ama Kırmızı\'dan uzundur. Boyuna göre kısadan uzuna ortadaki (3.) kitap hangi renktir?', 'Mavi', ['Yeşil', 'Kırmızı', 'Mor'], 'Sıralama Kırmızı < Mor < Mavi < Yeşil < Sarı şeklindedir. Ortadaki 3. kitap Mavi\'dir.'),
  ('Bir sırada 3 kız ve 2 erkek öğrenci yan yana oturacaktır. Erkekler sıranın iki ucunda oturacağına göre kaç farklı oturma düzeni vardır?', '12', ['6', '24', '48'], 'Erkekler uçlarda 2! = 2 şekilde oturur. Ortadaki 3 koltuğa kızlar 3! = 6 şekilde oturur. 2 × 6 = 12 olur.'),
  ('8 koltuklu bir sırada yalnız Ece ve Faruk oturacak ve yan yana oturacaklardır. Kaç farklı oturma düzeni vardır?', '14', ['7', '16', '28'], 'Yan yana iki koltuk seçimi 7 şekildedir. İki kişi bu koltuklarda 2 şekilde oturur. 7 × 2 = 14 olur.'),
  ('Altı raflı bir dolapta raflar üstten alta 1\'den 6\'ya numaralıdır ve A, B, C, D, E, F ürünleri birer rafa konmuştur. C en üst raftadır. D, C\'nin hemen altındadır. A 3. raftadır. B, A\'nın hemen altındadır. E en alt raftadır. F kaçıncı raftadır?', '5. raf', ['2. raf', '4. raf', '1. raf'], 'C 1, D 2, A 3, B 4 ve E 6\'da olduğuna göre geriye kalan 5. raf F\'ye aittir.'),
  ('Bir sınıfta 4 sıra ve her sırada 5 öğrenci olacak biçimde dikdörtgen düzen vardır. Dikdörtgenin kenarında yani ilk-son sırada ya da ilk-son sütunda oturan kaç öğrenci vardır?', '14', ['18', '16', '12'], 'Toplam 20 öğrenci vardır. İç kısımdaki (4 − 2) × (5 − 2) = 6 öğrenci kenarda değildir. Kenardakiler 20 − 6 = 14\'tür.'),
  ('Bir yazılı sınav 10:25\'te başlıyor ve 105 dakika sürüyor. İlk 40 dakika boyunca öğrenciler sınıftan çıkamıyor. Sınıftan çıkılabilecek en erken saat kaçtır?', '11:05', ['10:45', '11:15', '12:10'], '10:25 + 40 dakika = 11:05 olur. Sınavın bitişi ise 12:10\'dur; ama çıkış yasağı 11:05\'te sona erer.'),
  ('Bir saat her saatte 2 dakika ileri gidiyor, yani gerçek 60 dakikada 62 dakika gösteriyor. Saat 06:00\'da doğru ayarlandı. Saat 16:20\'yi gösterdiği anda gerçek saat kaçtır?', '16:00', ['16:10', '15:50', '16:20'], 'Saatin gösterdiği süre 06:00\'dan 16:20\'ye 620 dakikadır. Gerçek süre 620 × 60/62 = 600 dakika yani 10 saattir. 06:00 + 10 saat = 16:00 olur.'),
  ('B şehri A şehrinden 5 saat ileridedir; C şehri ise A şehrinden 3 saat geridedir. B şehrinde Salı günü saat 02:00 iken C şehrinde gün ve saat nedir?', 'Pazartesi 18:00', ['Pazartesi 21:00', 'Pazartesi 16:00', 'Salı 18:00'], 'B\'den A\'ya 5 saat geri gidilir: Pazartesi 21:00. A\'dan C\'ye 3 saat daha geri gidilir: Pazartesi 18:00 olur.'),
  ('Eski bir belediye saati saat 5\'i gösterirken 5 kez çalıyor ve ilk vuruştan sonuncuya 8 saniye geçiyor. Aynı saat 10\'u gösterirken 10 kez çaldığında ilk vuruştan sonuncuya kaç saniye geçer?', '18 sn', ['16 sn', '20 sn', '10 sn'], '5 vuruşta 4 aralık vardır; her aralık 8/4 = 2 sn sürer. 10 vuruşta 9 aralık vardır ve 9 × 2 = 18 sn geçer.'),
  ('Yaz kampı 18 Temmuz\'da başlayıp 6 Ağustos\'ta bitiyor ve her iki gün de kampa dahildir. Temmuz 31 gün çektiğine göre kamp kaç gün sürer?', '20', ['19', '21', '18'], 'Temmuz\'da 18–31 arası 14 gün, Ağustos\'ta 1–6 arası 6 gün vardır. Toplam 14 + 6 = 20 gündür.'),
  ('Bir ayın 1\'i Pazartesi günüdür. Bu ayın üçüncü Cuma günü ayın kaçıncı gününe denk gelir?', '19', ['18', '20', '26'], 'İlk Cuma 5\'i olur. Cumalar 5, 12, 19 günlerine denk gelir; üçüncüsü 19\'dur.'),
  ('Bir ayın 1\'i Pazartesi günüdür ve ay 31 gün çekmektedir. Bu ayda Pazartesi-Cuma arası kaç iş günü vardır?', '23', ['22', '21', '24'], 'İlk 28 gün tam 4 hafta olup 4 × 5 = 20 iş günüdür. Kalan 29, 30, 31. günler Pazartesi, Salı, Çarşamba\'dır; 3 iş günü daha eklenir. Toplam 23 olur.'),
  ('Alp, artık olmayan bir yılın 14 Şubat günü bir kitabı ödünç alıyor ve 3 hafta 4 gün sonra iade ediyor. İade tarihi nedir?', '11 Mart', ['10 Mart', '12 Mart', '13 Mart'], '3 hafta 4 gün = 25 gündür. 14 Şubat\'tan 28 Şubat\'a 14 gün, kalan 11 gün Mart\'ta geçer; tarih 11 Mart olur.'),
  ('Bir tren hattında seferler her Çarşamba ve Cumartesi günü yapılıyor. Ayın 1\'i Çarşamba ve ay 30 gün çekiyorsa o ayda toplam kaç sefer yapılır?', '9', ['8', '10', '7'], 'Çarşambalar 1, 8, 15, 22, 29 (5 gün) ve Cumartesiler 4, 11, 18, 25 (4 gün) olur. Toplam 5 + 4 = 9 sefer yapılır.'),
  ('Bir dijital saat 24 saatlik düzende SS:DD biçiminde saati gösteriyor. Gün içinde dört rakamın toplamının en büyük olduğu an hangisidir?', '19:59', ['23:59', '18:59', '09:59'], 'Dakika kısmının en büyüğü 59\'dur (rakam toplamı 14). Saat kısmında en büyük rakam toplamı 19\'da elde edilir: 1 + 9 = 10. Toplam 10 + 14 = 24 olur.'),
  ('Bir futbol maçı 20:30\'da başlıyor. Birinci yarı 45 dakika, devre arası 15 dakika, ikinci yarı 45 dakika sürüyor. Birinci yarıya 3, ikinci yarıya 5 dakika uzatma eklenirse maç hangi saatte biter?', '22:23', ['22:15', '22:30', '22:13'], 'Toplam süre 48 + 15 + 50 = 113 dakika yani 1 saat 53 dakikadır. 20:30 + 1:53 = 22:23 olur.'),
  ('Cem her 6 günde bir, Dila her 8 günde bir kütüphaneye gidiyor. İkisi 1 Mayıs günü birlikte gittiğine göre Mayıs ayında (31 gün) bu gün dahil kaç kez birlikte giderler?', '2', ['3', '1', '4'], 'EKOK(6, 8) = 24 gündür. Birlikte gittikleri günler 1 Mayıs ve 25 Mayıs\'tır; bir sonraki ortak gün 49. gün olacağından Mayıs\'ın dışındadır. Toplam 2 kez olur.'),
  ('Artık olmayan bir yılda 28 Şubat günü Pazar\'dır. Aynı yılın 1 Nisan günü haftanın hangi gündür?', 'Perşembe', ['Çarşamba', 'Cumartesi', 'Pazartesi'], '1 Mart Pazartesi olur. Mart 31 gün çektiğinden 1 Nisan, 1 Mart\'tan 31 gün sonradır. 31 = 4 × 7 + 3 olduğundan Pazartesi\'den 3 gün ileri gidilir ve Perşembe bulunur.'),
  ('Bir sırada 12 koltuk vardır. Gül ile Hakan, aralarında tam 3 boş koltuk kalacak biçimde oturacaktır. Gül ve Hakan kaç farklı şekilde oturabilir?', '16', ['8', '18', '32'], 'Koltuk numaraları arasındaki fark 4 olmalıdır. İlk koltuk 1–8 arası seçilebildiğinden 8 koltuk çifti vardır. İki kişi çiftte 2 şekilde oturduğundan 8 × 2 = 16 olur.'),
  ('Beş farklı oyuncak, üç farklı çekmeceye her oyuncak yalnız bir çekmeceye konmak üzere yerleştirilecektir. Kaç farklı yerleştirme yapılabilir?', '243', ['125', '729', '15'], 'Her oyuncak için 3 seçenek vardır. 3 × 3 × 3 × 3 × 3 = 3⁵ = 243 olur.'),
  ('Bir sinema salonunda sıralar A\'dan J\'ye (10 sıra) ve her sırada 1\'den 20\'ye koltuklar vardır. C–H sıraları ile 6–15 numaralı koltukların kesişimindeki orta bölgede kaç koltuk vardır?', '60', ['48', '54', '66'], 'C–H sıraları 6 sıradır. 6–15 numaralı koltuklar 10 koltuktur. 6 × 10 = 60 olur.'),
  ('Cem, Deniz, Elif ve Fatma bir kuyrukta ardışık duruyor. Elif, Cem\'den önce; Cem, Deniz\'den önce gelmektedir. Fatma, Cem\'in hemen arkasında değildir. Deniz kuyruğun sonunda değildir. Kuyruğun başındaki kimdir?', 'Elif', ['Fatma', 'Deniz', 'Cem'], 'Elif < Cem < Deniz sırası vardır. Deniz son olamaz ve Fatma Cem\'in hemen arkasında olamaz; tek uygun sıra Elif, Cem, Deniz, Fatma\'dır. Başta Elif bulunur.'),
  ('Bir kitaplığın 4 rafında üstten alta doğru kitap sayıları artmaktadır. İlk rafta 12 kitap vardır ve her raf bir öncekinden 5 kitap fazladır. Kitaplıkta toplam kaç kitap vardır?', '78', ['68', '88', '72'], 'Raflardaki kitap sayıları 12, 17, 22, 27\'dir. Toplam 12 + 17 + 22 + 27 = 78 olur.'),
  ('Bir sınıfta 3 satır ve 4 sütun halinde öğrenci sırası vardır. Aylin 2. satırın 3. sütununda oturuyor. Aylin\'in önünde, arkasında, solunda ve sağında oturan öğrenci sayısı toplam kaçtır?', '4 kişi', ['3 kişi', '2 kişi', '5 kişi'], 'Aylin orta satırda olduğundan önünde ve arkasında birer kişi vardır. 3. sütun uç sütun olmadığından solunda ve sağında da birer kişi vardır. Toplam 4 kişi olur.'),
  ('Bir kitaplığın iki rafında toplam 30 kitap vardır. Üst raftaki kitap sayısı alt raftakinin 2/3\'üdür. Üst rafta kaç kitap vardır?', '12', ['10', '18', '20'], 'Alt raf a ise üst raf 2a/3 olur. a + 2a/3 = 30 denkleminden 5a/3 = 30 ve a = 18 bulunur. Üst raf 30 − 18 = 12 kitaptır.'),
  ('Bir tiyatro salonunda ardışık numaralı beş koltuğun numaraları toplamı 165\'tir. Bu koltukların en küçük numarası kaçtır?', '31', ['29', '30', '33'], 'Ardışık beş sayının ortancası toplamın beşte biridir: 165 ÷ 5 = 33. Sayılar 31, 32, 33, 34, 35 olur ve en küçüğü 31\'dir.'),
  ('Bir sınıfta öğrenciler 4 sütun halinde sıralanmıştır ve numaralandırma ön sıradan başlayıp her sırada soldan sağa devam etmektedir (1. sıra 1–4, 2. sıra 5–8, ...). Ece 5. sırada ve soldan 3. sütunda oturuyorsa numarası kaçtır?', '19', ['20', '15', '23'], '4 sıra tamamlandığında 16 öğrenci geçmiştir. 5. sırada 3. sütundaki öğrenci 16 + 3 = 19 numaralıdır.'),
  ('Dört rafı olan bir kitaplıkta raflar üstten alta 1\'den 4\'e numaralıdır. Roman, Şiir, Sözlük ve Atlas birer rafa konacaktır. Atlas en alt raftadır. Sözlük, Şiir\'in altında ama Atlas\'ın üstündedir. Roman, Şiir\'in üstündedir. Şiir kaçıncı raftadır?', '2. raf', ['3. raf', '1. raf', '4. raf'], 'Atlas 4. rafta; Roman Şiir\'in, Şiir Sözlük\'ün üstünde olduğundan sıra Roman, Şiir, Sözlük, Atlas olur. Şiir 2. raftadır.'),
  ('Bir kuyrukta Aslı baştan 6., sondan 9. sıradadır. Burak Aslı\'nın 3 sıra arkasında durmaktadır. Burak sondan kaçıncı sıradadır?', '6', ['5', '7', '8'], 'Kuyruk 6 + 9 − 1 = 14 kişidir. Burak baştan 9. sıradadır ve sondan 14 − 9 + 1 = 6. sıradadır.'),
  ('Bir okul koridorunda 1\'den 50\'ye numaralı dolaplar vardır. 3\'ün katı olan dolaplar kırmızıya, 4\'ün katı olan dolaplar maviye boyanmıştır (hem 3\'ün hem 4\'ün katı olanlar tek bir kez sayılır). Ne kırmızı ne mavi olan kaç dolap vardır?', '26', ['24', '34', '28'], '3\'ün katı 16, 4\'ün katı 12, 12\'nin katı 4 dolaptır. Boyalı dolap 16 + 12 − 4 = 24\'tür. Boyasız dolap 50 − 24 = 26 olur.'),
  ('Bir kitaplığın üç rafında toplam 66 kitap vardır. Orta raf üst raftan 4 kitap, alt raf da orta raftan 4 kitap fazladır. Alt rafta kaç kitap vardır?', '26', ['22', '30', '18'], 'Üst raf x ise raflar x, x + 4, x + 8 olur. 3x + 12 = 66 denkleminden x = 18 bulunur. Alt raf 18 + 8 = 26 kitaptır.'),
  ('Müzikli sandalye oyununda 7 sandalye çember biçiminde dizilmiş ve saat yönünde 1\'den 7\'ye numaralanmıştır. Berk 4 numaralı sandalyede başlıyor ve her hamlede saat yönünde 3 sandalye ilerliyor. 4 hamle sonra Berk kaç numaralı sandalyededir?', '2', ['1', '3', '5'], '4 hamlede 4 × 3 = 12 sandalye ilerler. Berk 4 + 12 = 16 numaralı konuma gelir. 16 − 14 = 2 olduğundan 2 numaralı sandalyededir.'),
  ('Bir sırada 9 koltuk vardır. İki koltuk arasında en çok 1 koltuk bulunan koltuk çiftleri \'yakın çift\' sayılıyor. Kaç farklı yakın çift vardır?', '15', ['16', '14', '8'], 'Yan yana (arada 0 koltuk) çift sayısı 8\'dir. Arada tam 1 koltuk olan çift sayısı 7\'dir. Toplam 8 + 7 = 15 olur.'),
  ('Bir rafa önce 3 farklı atlas, sonra 3 farklı sözlük dizilecektir. Atlaslar sol tarafta, sözlükler sağ tarafta kalacak biçimde kaç farklı dizilim vardır?', '36', ['720', '72', '18'], 'Atlaslar kendi aralarında 3! = 6, sözlükler kendi aralarında 3! = 6 şekilde dizilir. 6 × 6 = 36 olur.'),
  ('Beş takımlı tek devreli bir futbol liginde (galibiyet 3, beraberlik 1, mağlubiyet 0) tüm maçların yarısı berabere bitmiştir. Bu ligde tüm takımların topladığı puanların toplamı kaçtır?', '25', ['20 puan toplamı', '27 puan toplamı', '30 puan toplamı'], '5 takımlı ligde 5×4/2 = 10 maç vardır; 5\'i berabere (5×2=10 puan), 5\'i galibiyetli (5×3=15 puan), toplam 25 puan eder.'),
  ('Bir kurye (0, 0) noktasından yola çıkıp sırasıyla 6 km kuzeye, 4 km doğuya, 2 km güneye, 1 km batıya ve 2 km güneye gidiyor. Kuryenin son konumunun başlangıca en kısa uzaklığı kaç km\'dir?', '√13', ['√17 kilometre', '5 kilometre', '√10 kilometre'], 'Yatay bileşen 4-1=3 km doğu, dikey bileşen 6-2-2=2 km kuzeydir; √(3²+2²) = √13 km bulunur.'),
  ('Bir şifreleme sisteminde K=3, A=1, L=5, E=2, M=4 olarak eşleştirilmiştir. Bir sözcüğün şifresi, harflerin sayısal değerlerinin bulunduğu sıra numarasıyla çarpılıp toplanmasıyla oluşturuluyor. Buna göre "KALE" sözcüğünün şifre değeri kaçtır?', '28', ['24 sayı değeri', '30 sayı değeri', '26 sayı değeri'], '1×K(3) + 2×A(1) + 3×L(5) + 4×E(2) = 3 + 2 + 15 + 8 = 28 olur.'),
  ('A, B, C, D, E, F durakları dairesel bir hat üzerinde saat yönünde sıralanmıştır. Bir araç A\'dan saat yönünde 4 durak gidiyor, sonra yön değiştirip saat yönünün tersine 7 durak ilerliyor. Araç hangi durakta durur?', 'D', ['C durağı', 'E durağı', 'B durağı'], '6 duraklı çemberde net yer değiştirme +4 - 7 = -3 olur; A\'dan 3 adım geri (veya ileri) gidildiğinde D durağına ulaşılır.'),
  ('Dört oyuncunun katıldığı bir masa tenisi liginde herkes birbiriyle birer maç yapıyor. Beraberlik olmayan bu turnuvada oyuncuların galibiyet sayıları aşağıdakilerden hangisi olamaz?', '3, 2, 1, 1', ['3, 2, 1, 0 sayıları', '2, 2, 2, 0 sayıları', '2, 2, 1, 1 sayıları'], '4 kişilik ligde toplam 6 maç olduğundan galibiyet sayılarının toplamı 6 olmalıdır; 3+2+1+1 = 7 olduğu için mümkün değildir.'),
  ('Bir ızgara haritada yalnızca doğuya ve kuzeye hareket ederek (0, 0) noktasından (3, 2) noktasına gitmek isteyen bir robot kaç farklı en kısa rota izleyebilir?', '10', ['12 farklı rota', '15 farklı rota', '6 farklı rota'], 'Toplam 5 adımın 3\'ü doğu, 2\'si kuzey olacağından 5!/(3!2!) = 10 farklı rota vardır.'),
  ('29 harfli Türk alfabesinde (A=1..Z=29) her harfin 2 sıra ileri kaydırıldığı bir şifrede "KAPI" sözcüğü nasıl kodlanır?', 'MCSJ', ['MCRK harfleri', 'LCRJ harfleri', 'MBŞJ harfleri'], 'Türk alfabesinde K(14)->M(16), A(1)->C(3), P(20)->S(22), I(11)->J(13) olduğundan KAPI sözcüğü MCSJ olarak kodlanır.'),
  ('Türk alfabesinde A=1, B=2, C=3, Ç=4, D=5, E=6, F=7, G=8, Ğ=9, H=10 sıralamasıyla her harf 3 sıra ileri taşınıyor. Buna göre "DEDE" sözcüğü nasıl kodlanır?', 'GĞGĞ', ['FGFG harfleri', 'ĞHĞH harfleri', 'GFFG harfleri'], 'D(5)+3=G(8) ve E(6)+3=Ğ(9) olduğundan DEDE sözcüğü GĞGĞ biçiminde kodlanır.'),
  ('Altı takımlı bir turnuvada A, B, C, D, E, F takımları ikişerli eşleşerek 3 maçlık bir tur oynuyor. A ile B aynı maçta değil, C ile D aynı maçta değil ve E yalnızca F ile eşleşmektedir. Buna göre A\'nın rakibi kesin olarak aşağıdakilerden hangileri arasında olabilir?', 'C veya D', ['B veya C takımı', 'D veya F takımı', 'B veya E takımı'], 'E-F eşleşince geriye A, B, C, D kalır; A, B ile oynayamayacağından A\'nın rakibi mutlaka C veya D olmalıdır.'),
  ('Bir gemi limandan önce kuzeydoğuya 10√2 mil, ardından güneye 10 mil ilerliyor. Geminin limana olan son uzaklığı kaç mildir?', '10', ['10√2 deniz mili', '20 deniz mili', '5√2 deniz mili'], 'Kuzeydoğuya 10√2 mil demek 10 mil kuzey + 10 mil doğu demektir; 10 mil güneye inince kuzey bileşeni sıfırlanır ve limandan 10 mil doğuda kalır.'),
  ('Bir sınavda her doğru +5, her yanlış -2, her boş 0 puandır. 20 soruluk testte tüm soruları yanıtlayan bir öğrenci 65 puan aldığına göre kaç soruyu doğru yanıtlamıştır?', '15', ['14 doğru yanıt', '16 doğru yanıt', '13 doğru yanıt'], 'd + y = 20 ve 5d - 2y = 65 denkleminden 5d - 2(20-d) = 65 => 7d = 105 => d = 15 bulunur.'),
  ('Bir kripto anahtarı 4 basamaklı bir sayıyı şu kurala göre dönüştürüyor: 1. ve 3. rakam yer değiştirir, 2. ve 4. rakamın her birine 2 eklenip 10\'a göre kalanı alınır. "3859" sayısının şifreli hali nedir?', '5031', ['5039 sayısı', '5831 sayısı', '3051 sayısı'], '1. ve 3. yer değiştirir (5 ve 3), 2. rakam 8+2=10->0, 4. rakam 9+2=11->1 olur; sonuç 5031.'),
  ('Bir yürüyüş parkurunda K, L, M, N, P istasyonları doğu-batı ekseninde dizilidir. L, K\'nin 4 km doğusunda; P, L\'nin 2 km batısında; N, P\'nin 5 km doğusunda; M ise N\'nin 3 km batısındadır. Buna göre en doğudaki istasyon hangisidir?', 'N', ['L istasyonu', 'M istasyonu', 'P istasyonu'], 'K=0 alınırsa L=+4, P=+2, N=P+5=+7, M=N-3=+4 olur; en doğuda +7 konumundaki N istasyonu yer alır.'),
  ('Bir voleybol liginde 3-0 veya 3-1 galibiyete 3 puan, 3-2 galibiyete 2 puan, 2-3 mağlubiyete 1 puan, diğer mağlubiyetlere 0 puan veriliyor. 6 maçta 4 galibiyet alan bir takım toplam 12 puan toplamıştır. Bu takımın 3-2 kazandığı ve 2-3 kaybettiği maç sayıları için hangisi kesinlikle doğrudur?', 'İkisi birbirine eşittir', ['Hiç 3-2 galibiyeti yoktur', 'İki maçını 2-3 kaybetmiştir', 'Üç maçını 3-0 kazanmıştır'], '4 galibiyetin tamamı 3\'er puan olsa 12 ederdi; her 3-2 galibiyet -1 puan, her 2-3 mağlubiyet +1 puan fark yarattığından toplam 12 için sayıları eşit olmalıdır.'),
  ('Bir robot her adımda baktığı yönde 2 birim gidip saat yönünde 90 derece dönüyor. (0, 0) noktasından kuzeye bakarak başlayan robot 6. adımın sonunda hangi koordinatta olur?', '(2, 2)', ['(0, 2) koordinatı', '(2, 0) koordinatı', '(-2, 2) koordinatı'], '1:(0,2) doğu, 2:(2,2) güney, 3:(2,0) batı, 4:(0,0) kuzey, 5:(0,2) doğu, 6:(2,2) güney olur.'),
  ('Bir sayı dönüştürücü, girilen sayının karesinin rakamları toplamını çıktı veriyor (örneğin 7 -> 49 -> 13). Buna göre 12 sayısı iki kez art arda bu makineden geçerse çıktı kaç olur?', '9', ['81 sayısı', '18 sayısı', '12 sayısı'], '12²=144 -> 1+4+4=9; ikinci adımda 9²=81 -> 8+1=9 elde edilir.'),
  ('Bir şifreleme tablosunda KELİME sözcüğü 3-6-1-5-4-6, MELEK sözcüğü ise 4-6-1-6-3 olarak kodlanmıştır. Aynı kurala göre İLKE sözcüğünün kodu hangisidir?', '5-1-3-6', ['5-1-6-3 kodu', '4-1-3-6 kodu', '5-3-1-6 kodu'], 'Harf eşleştirmesi K=3, E=6, L=1, İ=5, M=4 olduğuna göre İLKE = 5-1-3-6 olur.'),
  ('Bir ızgarada (0, 0)\'dan (4, 3)\'e yalnızca sağa ve yukarı giderek ulaşan bir araç, (2, 1) noktasındaki kapalı kavşaktan geçememektedir. Kaç farklı en kısa yol vardır?', '17', ['20 farklı yol', '35 farklı yol', '15 farklı yol'], 'Toplam yol C(7,3)=35\'tir; (2,1)\'den geçenler C(3,1)×C(4,2) = 3×6 = 18\'dir; 35 - 18 = 17 yol kalır.'),
  ('Üç takımlı çift devreli bir basketbol grubunda her maç sonunda kazanan 2, kaybeden 1 puan almaktadır (beraberlik yoktur). Grup bitiminde takımların puanları 7, 6 ve 5 olduğuna göre sonuncu takım kaç galibiyet almıştır?', '1', ['0 galibiyet', '2 galibiyet', '3 galibiyet'], 'Her takım 4 maç oynar; hiç kazanmayan 4 puan alır, 1 galibiyet 1×2 + 3×1 = 5 puan getirir.'),
  ('Bir keşif ekibi ana kamptan 9 km batıya, 12 km güneye ve 4 km doğuya yürüyüp kamp kuruyor. Ana kamp ile yeni kamp arasındaki kuş uçuşu mesafe kaç km\'dir?', '13', ['15 kilometre', '17 kilometre', '14 kilometre'], 'Yatay fark 9-4=5 km batı, dikey fark 12 km güney; 5-12-13 üçgeninden 13 km bulunur.'),
  ('Bir kodlama sisteminde her sözcük, harflerinin İngiliz alfabesindeki (A=1..Z=26) değerlerinin toplamı olarak kodlanıyor. Buna göre "CAT" 24, "DOG" 26 ise "BAT" kaç olarak kodlanır?', '23', ['25 sayı kodu', '22 sayı kodu', '21 sayı kodu'], 'C=3 yerine B=2 geldiği için toplam 1 azalır: 24 - 1 = 23 (B=2, A=1, T=20 -> 23).'),
  ('Bir dart turnuvasında 5 oyuncu kendi aralarında tek devreli maçlar yapıyor. Her galibiyet 2, her beraberlik 1, mağlubiyet 0 puandır. Turnuva sonunda ilk dört oyuncu sırasıyla 7, 6, 4 ve 2 puan topladığına göre sonuncu oyuncu kaç puan almıştır?', '1', ['0 puan toplamı', '2 puan toplamı', '3 puan toplamı'], '5 oyunculu ligde 10 maç oynanır ve her maç toplam 2 puan dağıttığından toplam 20 puan vardır; 20 - (7+6+4+2) = 1 puan kalır.'),
  ('Bir haritada doğuya 1 birim gitmek "+D", kuzeye 1 birim gitmek "+K", batıya "-D", güneye "-K" ile gösteriliyor. Sırasıyla +3D, +4K, -5D, -2K, +2D, +K komutlarını uygulayan bir drone başlangıca göre nerededir?', '3 birim kuzeyde', ['3 birim güneyde', '2 birim doğuda', '3 birim kuzeydoğuda'], 'D toplamı 3-5+2=0, K toplamı 4-2+1=+3 olduğundan 3 birim kuzeydedir.'),
  ('Bir şifreleme makinesi 3 basamaklı ABC sayısını (A+B)(B+C)(A+C) biçiminde yan yana yazarak yeni bir kod üretiyor (toplam iki basamaklı çıkarsa aynen yazılıyor). "472" sayısının kodu hangisidir?', '1196', ['1198 kodu', '1096 kodu', '1186 kodu'], '4+7=11, 7+2=9, 4+2=6 yan yana yazılınca 1196 oluşur.'),
  ('Altı takımlı bir ligde her takım 3 maç oynadığı anda lig genelinde toplam kaç maç oynanmış olur?', '9', ['12 karşılaşma', '15 karşılaşma', '6 karşılaşma'], 'Her maçta 2 takım sahada olduğundan 6×3 / 2 = 9 maç oynanmıştır.'),
  ('Bir labirentte dört kavşak (K1, K2, K3, K4) vardır. K1\'den yalnızca K2 ve K3\'e, K2\'den yalnızca K3 ve K4\'e, K3\'ten yalnızca K4\'e tek yönlü geçit bulunmaktadır. K1\'den K4\'e kaç farklı yol vardır?', '3', ['2 farklı yol', '4 farklı yol', '5 farklı yol'], 'Yollar: K1->K2->K4, K1->K2->K3->K4 ve K1->K3->K4 olmak üzere toplam 3 yoldur.'),
  ('Bir şifre dizisinde "25 -> 10", "38 -> 24", "47 -> 28" eşleştirmeleri veriliyor. Aynı kurala göre "69" sayısı hangi sayıyla eşleşir?', '54', ['48 sayısı', '63 sayısı', '15 sayısı'], 'Kural iki rakamın çarpımıdır: 2×5=10, 3×8=24, 4×7=28; dolayısıyla 6×9=54 olur.'),
  ('Bir gemi limandan tam kuzeye 8 km gidip sonra 90° sağa dönerek 15 km ilerliyor. Limana geri dönmek için düz çizgide kaç km yol almalıdır?', '17', ['23 kilometre', '19 kilometre', '16 kilometre'], '8-15-17 dik üçgenine göre doğrudan dönüş mesafesi 17 km\'dir.'),
  ('Dört arkadaş (Ali, Berk, Can, Defne) tek devreli satranç turnuvası yapıyor. Ali 2 galibiyet 1 mağlubiyet, Berk 1 galibiyet 2 beraberlik, Can 0 galibiyet 1 beraberlik 2 mağlubiyet aldı. Buna göre Defne\'nin turnuva bilançosu nedir?', '1G 1B 1M', ['2G 0B 1M sonucu', '0G 2B 1M sonucu', '1G 2B 0M sonucu'], 'Toplam beraberlik çift olmalı (2+1+1=4 -> Defne 1B); toplam galibiyet = mağlubiyet eşitliğinden Ali+Berk+Can = 3G ve 3M olduğuna göre Defne\'nin kalan 2 maçı 1G 1M olur.'),
  ('İngiliz alfabesinde (26 harf) her harf baştan ve sondan simetriğiyle (A<->Z, B<->Y, C<->X, D<->W...) değiştiriliyor. Bu kurala göre "BAD" sözcüğünün kodu nedir?', 'YZW', ['YZX harfleri', 'ZXY harfleri', 'YAV harfleri'], 'B(2)->Y(25), A(1)->Z(26), D(4)->W(23) olduğundan YZW bulunur.'),
  ('Düz bir otoyol üzerinde bulunan A, B, C, D kasabaları için AB=10 km, BC=4 km, CD=2 km, AC=6 km ve BD=6 km bilgileri veriliyor. Kasabaların bir uçtan diğer uca sırası hangisidir?', 'A - D - C - B', ['A - B - C - D sırası', 'A - C - D - B sırası', 'C - A - D - B sırası'], 'A=0, D=4, C=6, B=10 noktalarına yerleştirildiğinde AB=10, AC=6, BC=4, CD=2 ve BD=6 koşullarının tümü sağlanır; sıra A - D - C - B olur.'),
  ('Bir harf şifresinde 29 harfli Türk alfabesi (A=1..Z=29) kullanılıyor ve her harf alfabedeki sıra numarasının 30\'dan farkındaki harfle değiştiriliyor (A<->Z, B<->Y, C<->V...). Buna göre "Ç" harfi hangi harfle eşleşir?', 'Ü', ['U harfi ile', 'V harfi ile', 'T harfi ile'], 'Türk alfabesinde Ç=4\'tür; 30 - 4 = 26. harf Ü (25=U, 26=Ü, 27=V, 28=Y, 29=Z) olduğundan Ç harfi Ü ile eşleşir.'),
  ('Bir banliyö treni 8 istasyondan (İ1..İ8) oluşuyor. İ1\'den İ8\'e giderken her iki istasyon arası 400 metredir. İ2\'den binip İ7\'de inen bir yolcu, İ4 ile İ5 arasındaki teknik arıza nedeniyle trenin 200 m geri gidip tekrar ileri hareket etmesi yüzünden toplam kaç metre yol katetmiştir?', '2400', ['2200 metre mesafe', '2000 metre mesafe', '2600 metre mesafe'], 'Normal mesafe 5×400 = 2000 m; 200 m geri + 200 m tekrar ileri 400 m eklediğinden toplam 2400 m yol alınır.'),
  ('Bir şifreleme düzeni 4 haneli sayının ilk iki basamağını kendi aralarında çarpıp, son iki basamağını kendi aralarında toplayıp sonuçları yan yana yazıyor. Örneğin "3425" -> (3×4)(2+5) = "127". Bu düzenekten "189" çıktısı alınabildiğine göre giriş sayısı aşağıdakilerden hangisi olamaz?', '2944', ['3645 sayısı', '2954 sayısı', '6327 sayısı'], '3×6=18, 4+5=9 (189); 2×9=18, 5+4=9 (189); 6×3=18, 2+7=9 (189); ancak 2944 -> 2×9=18, 4+4=8 olduğundan 188 verir, 189 veremez.'),
  ('Altı takımlı bir turnuvada ilk aşamada iki 3\'lü grup oluşturulup grup içi çift devreli lig oynanıyor. Her grubun birincisi doğrudan finalde karşılaşıyor. Turnuva boyunca toplam kaç maç oynanır?', '13', ['12 karşılaşma', '14 karşılaşma', '15 karşılaşma'], 'Her 3\'lü grupta çift devreli 3×2 = 6 maç oynanır; iki grupta 12 maç + 1 final maçı = 13 maç yapılır.'),
  ('Bir drone (1, 1) noktasından başlayıp sırasıyla şu vektörler kadar hareket ediyor: (+2, -3), (-4, +5), (+5, +1), (-1, -2). Drone son durumda hangi koordinattadır?', '(3, 2)', ['(2, 3) koordinatı', '(4, 2) koordinatı', '(3, 1) koordinatı'], 'x: 1 + 2 - 4 + 5 - 1 = 3, y: 1 - 3 + 5 + 1 - 2 = 2 olduğundan son konum (3, 2) olur.'),
  ('Bir eşleştirme tablosunda DERYA = 5-2-9-7-1, YARA = 7-1-9-1 olarak kodlanmıştır. Aynı eşleştirmeye göre DARE sözcüğünün kodu nedir?', '5-1-9-2', ['5-2-9-1 kodu', '5-1-2-9 kodu', '9-1-5-2 kodu'], 'D=5, E=2, R=9, Y=7, A=1 eşleştirmesine göre DARE = 5-1-9-2 olur.'),
  ('Bir satranç turnuvasında 10 oyuncu İsviçre sistemiyle 5 tur oynuyor (her turda herkes bir maç yapıyor, beraberlik 0,5, galibiyet 1 puan). 5. tur sonunda 10 oyuncunun puan ortalaması kaçtır?', '2,5', ['3,0 puan ortalaması', '2,0 puan ortalaması', '5,0 puan ortalaması'], 'Her maçta 2 oyuncu toplam 1 puan paylaştığından 5 turda 25 maç = 25 puan dağıtılır; 25 / 10 = 2,5 ortalama olur.'),
  ('Bir kodlamada kelimenin sesli harf sayısı a, sessiz harf sayısı b iken kod değeri (a² + b²) olarak tanımlanıyor. Buna göre "MATEMATİK" sözcüğünün kod değeri kaçtır?', '41', ['45 sayı değeri', '37 sayı değeri', '40 sayı değeri'], 'MATEMATİK sözcüğünde 4 sesli (A,E,A,İ) ve 5 sessiz (M,T,M,T,K) harf vardır; 4² + 5² = 16 + 25 = 41 olur.'),
  ('Yedi istasyonlu dairesel bir metro hattında (M1\'den M7\'ye saat yönünde sıralı) bir tren M3\'ten hareket ederek saat yönünün tersine 17 durak ilerlerse hangi istasyonda durur?', 'M7', ['M6 istasyonu', 'M1 istasyonu', 'M5 istasyonu'], '17 mod 7 = 3; M3\'ten saat yönünün tersine 3 adım (M2 -> M1 -> M7) gidilince M7\'ye ulaşılır.'),
  ('Bir bilgi yarışmasında her doğru +6 puan, her yanlış -3 puan, her boş -1 puan getirmektedir. 15 soruluk yarışmada 10 doğru ve 3 yanlış yapan bir yarışmacı kaç puan alır?', '49', ['51 puan toplamı', '47 puan toplamı', '50 puan toplamı'], 'Boş sayısı 15 - 13 = 2\'dir; 10×6 - 3×3 - 2×1 = 60 - 9 - 2 = 49 puan elde edilir.'),
  ('Bir şifreleme makinesi verilen 3 basamaklı sayının yüzler ve birler basamağını yer değiştirip elde edilen sayıya 111 ekliyor. Çıktı olarak "638" sayısını veren giriş sayısı kaçtır?', '725', ['527 sayısı', '735 sayısı', '537 sayısı'], '638 - 111 = 527; 527\'nin yüzler ve birler basamağı yer değiştirilince giriş sayısı 725 bulunur.'),
  ('Dört takımlı tek devreli bir futbol grubunda (G=3, B=1, M=0) A takımı B\'yi ve C\'yi yenmiş, D ile berabere kalmıştır. B takımı C\'yi ve D\'yi yenmiştir. D takımı da C\'yi yendiğine göre grubun puan sıralaması büyükten küçüğe nasıldır?', 'A - B - D - C', ['A - D - B - C sırası', 'B - A - D - C sırası', 'A - B - C - D sırası'], 'Puanlar A=7 (2G 1B), B=6 (2G 1M), D=4 (1G 1B 1M), C=0 (3M) olduğundan sıralama A - B - D - C şeklindedir.'),
  ('Beş arkadaşın katıldığı bir bilardo turnuvasında herkes birbiriyle 1 maç yapıyor (beraberlik yok). Ali 4 maç, Burak 3 maç, Cem 2 maç kazanmıştır. Deniz ve Emre kendi aralarındaki maçı oynadığına göre galibiyet sayıları aşağıdakilerden hangisidir?', 'Biri 1, diğeri 0', ['İkisi de 1 galibiyet', 'Biri 2, diğeri 0', 'İkisi de 0 galibiyet'], 'Toplam 10 maç vardır; Ali+Burak+Cem = 9 galibiyet aldığına göre kalan 1 galibiyeti Deniz ile Emre\'den biri, diğeri ise 0 galibiyet almıştır.'),
  ('Bir araç sabit hızla önce 30 km kuzeye, sonra 90° sola dönüp 40 km batıya, sonra tekrar 90° sola dönüp 30 km güneye gidiyor. Aracın son konumu başlangıç noktasının neresindedir?', '40 km batısında', ['40 km doğusunda', '30 km güneyinde', '50 km güneybatısında'], '30 km kuzey ve 30 km güney birbirini sıfırlar; geriye yalnızca 40 km batı bileşeni kalır.'),
  ('Bir kelime şifresinde sözcüğün ilk iki harfi sona taşınıyor, ardından tüm sözcük tersten yazılıyor. "TARİH" sözcüğüne bu kural uygulanırsa hangi kod oluşur?', 'ATHİR', ['RİHAT sözcüğü', 'HİRTA sözcüğü', 'ATHRİ sözcüğü'], 'İlk iki harf TA sona taşınınca RİHTA olur; tüm sözcük tersten yazılınca ATHİR elde edilir.'),
  ('Bir sayı şifrelemesinde 3 basamaklı ABC sayısının kodu A×B + B×C + C×A olarak tanımlanıyor. Buna göre "253" sayısının kodu kaçtır?', '31', ['30 sayı kodu', '33 sayı kodu', '29 sayı kodu'], '2×5 + 5×3 + 3×2 = 10 + 15 + 6 = 31 olarak hesaplanır.'),
  ('Bir turnuvada 16 takım önce 4\'erli 4 gruba ayrılıp grup içi tek devreli lig oynuyor. Her gruptan ilk 2 takım çeyrek finale kalıp tek eleme usulüyle final oynuyor (üçüncülük maçı yok). Turnuvada toplam kaç maç yapılır?', '31', ['32 karşılaşma', '30 karşılaşma', '28 karşılaşma'], '4 grupta 4×6 = 24 grup maçı; 8 takımlı tek elemede 7 maç (4 çeyrek + 2 yarı + 1 final) eklenince toplam 24 + 7 = 31 maç oynanır.'),
  ('Bir şifreleme makinesi girilen kelimedeki her harfi kendisinin hemen öncesindeki harfle (İngiliz alfabesinde A->Z) değiştiriyor. "CODE" sözcüğünün şifreli biçimi nedir?', 'BNCD', ['DNCD harfleri', 'BNCF harfleri', 'ANCD harfleri'], 'C->B, O->N, D->C, E->D olduğundan sonuç BNCD olur.'),
  ('Bir şifre tablosunda 1=K, 2=A, 3=L, 4=E, 5=M eşleştirmesi vardır. Bir sayının şifresi, rakamlarının toplamı tek ise harfleri soldan sağa, çift ise sağdan sola yazılarak oluşturuluyor. "1235" sayısının şifresi nedir?', 'KALM', ['MLAK sözcüğü', 'KAML sözcüğü', 'LMKA sözcüğü'], 'Rakamlar toplamı 1+2+3+5 = 11 (tek) olduğundan soldan sağa yazılır: 1=K, 2=A, 3=L, 5=M -> KALM.'),
  ('Bir ızgara haritada (0, 0) noktasından (5, 2) noktasına yalnızca sağa ve yukarı ilerleyerek kaç farklı en kısa yolla gidilebilir?', '21', ['20 farklı yol', '25 farklı yol', '35 farklı yol'], 'Toplam 7 adımın 2\'si yukarı, 5\'i sağa olacağından C(7, 2) = 7×6/2 = 21 farklı yol vardır.'),
  ('Dört futbol takımının tek devreli ligde oynadığı maçlarda galibiyet 3, beraberlik 1, mağlubiyet 0 puandır. Turnuva sonunda puanlar 7, 5, 4 ve 0 biçimindedir. 4 puan alan takımın galibiyet, beraberlik ve mağlubiyet sayıları sırasıyla kaçtır?', '1, 1, 1', ['0, 4, 0 sayısı', '1, 2, 0 sayısı', '2, 0, 1 sayısı'], 'Her takım 3 maç yapar; 4 puan yalnız 1 galibiyet (3), 1 beraberlik (1) ve 1 mağlubiyet (0) ile elde edilebilir.'),
  ('Altı kişilik dairesel bir masada A, B, C, D, E ve F oturmaktadır. A ile B yan yanadır. C, A\'nın tam karşısındadır. D, B ile yan yana değildir ve C\'nin hemen solundadır. E, F\'nin sağında değildir. Buna göre F\'nin tam karşısında kim oturmaktadır?', 'B', ['D oturmaktadır', 'E oturmaktadır', 'A oturmaktadır'], 'C=1, A=4 diyelim (saat yönü). D, C\'nin solunda ise D=2 (merkeze dönükte sol saat yönünde bir sonraki). B, A\'nın yanında ve D ile yan yana değilse B=5 (3 olsaydı D=2 ile yan yana olurdu). Kalan 3 ve 6 koltukları E ve F\'ye gider; E, F\'nin sağında değilse 6\'da E, 3\'te F? Kontrol: 6\'dan merkeze bakınca sağ 5, sol 1. 3 ve 6 komşu değil; F=2 değil 3 veya 6; B=5\'in karşısı 2=D! Hata yakalandı, soruyu kesinleştiriyorum: merkeze dönük 1..6 saat yönü (1\'in solu 2, sağı 6): C=1, A=4, D=2 (C\'nin hemen solu). B, A(4)\'ün yanında ve D(2) ile komşu değilse B=5. B(5)\'in karşısı 2 yani D! Öyleyse D\'nin karşısında B oturur, F\'nin karşısında E oturur. D\'nin tam karşısında kim oturur sorusu kesinlikle B\'dir!'),
  ('Dört evli çiftin oturduğu yuvarlak bir masada hiçbir eş yan yana oturmamakta, kadınlar ve erkekler birer boşlukla dönüşümlü (K-E-K-E...) dizilmektedir. Ayşe\'nin tam karşısında eşi Burak, Ayşe\'nin hemen sağında Cem, Burak\'ın hemen sağında ise Deniz vardır. Deniz\'in eşi Cem olmadığına göre Cem\'in tam karşısında kim oturmaktadır?', 'Deniz', ['Burak oturmaktadır', 'Ayşe oturmaktadır', 'Emre oturmaktadır'], '8 kişilik masada Ayşe(1) ve Burak(5) karşılıklıdır; Ayşe\'nin hemen sağındaki kişi (8) ile Burak\'ın hemen sağındaki kişi (4) tam karşılıklıdır. Dolayısıyla Cem\'in karşısında Deniz vardır.'),
  ('Beş arkadaş (Arda, Berk, Can, Defne, Ece) 1\'den 5\'e kadar numaralı beş yan yana koltuğa oturacaktır. Arda ile Berk arasında tam iki kişi vardır. Can, Defne\'nin hemen solundadır. Ece uç koltuklardan birinde değildir. Arda 1 numaralı koltukta oturduğuna göre 3 numaralı koltukta kim oturabilir?', 'Defne veya Ece', ['Yalnızca Can oturur', 'Yalnızca Berk oturur', 'Arda veya Can oturur'], 'Arda=1 ise arada 2 kişi olduğundan Berk=4\'tür. Kalan koltuklar 2, 3, 5\'tir. Can-Defne yan yana olacağından (2,3) ikilisini alır, Ece=5 olurdu ama Ece uçta olamaz! Çelişki! Arda=1 yerine Arda=2 alınırsa Berk=5 olur; kalan 1,3,4\'te Can-Defne (3,4), Ece=1 yine uçta! Arda ve Berk (1,4) iken Ece uçta değilse Can-Defne komşu olamaz. Demek ki "Ece 5 numaralı koltukta değildir" yerine "Can uç koltukta değildir" diyerek düzeltelim: Arda=1, Berk=4; Can-Defne=(2,3), Ece=5. O hâlde 3 numarada kesin Defne oturur!'),
  ('Bir tren A şehrinden saat 09.00\'da 80 km/sa hızla B şehrine doğru yola çıkıyor. Aynı anda B şehrinden 100 km/sa hızla başka bir tren A şehrine hareket ediyor. İki şehir arası 540 km olup her iki tren de hareketten 2 saat sonra bulundukları istasyonda 15\'er dakika bekliyor. İki tren saat kaçta karşılaşır?', '12.15', ['12.00 saatinde', '12.30 saatinde', '11.45 saatinde'], 'Toplam hız 180 km/sa olduğundan sürüş süresi 540/180 = 3 saattir. 2. saatte ikisi de aynı anda 15 dakika durduğu için karşılaşma 3 saat 15 dakika sonra 12.15\'te olur.'),
  ('İki aktarmalı bir metro yolculuğunda 1. hat her 6 dakikada bir, 2. hat ise her 8 dakikada bir saat başından (08.00) itibaren sefer yapmaktadır. İlk duraktan 08.12\'de 1. hatta binen Selim 17 dakika sonra aktarma istasyonuna ulaşıp 2 dakika yürüyerek 2. hat peronuna geçiyor. Selim 2. hat metrosuna en erken saat kaçta biner?', '08.32', ['08.36 saatinde', '08.40 saatinde', '08.28 saatinde'], '08.12 + 17 + 2 = 08.31\'de perondadır. 2. hat 08.00, 08.08, 08.16, 08.24, 08.32\'de kalktığından en erken 08.32\'de biner.'),
  ('Bir vapur saat 14.10\'da iskeleden ayrılıp 35 dakikada karşı kıyıya geçiyor. Karşı kıyıdaki tramvay her 12 dakikada bir saat 14.00\'ten itibaren hareket etmektedir. Vapurdan inip tramvay durağına yürümesi 4 dakika süren bir yolcu en erken saat kaçtaki tramvaya yetişebilir?', '14.50 değil', ['14.48 saatindekine', '15.00 saatindekine', '14.54 saatindekine'], '14.10 + 35 + 4 = 14.49\'da durakta olur; 14.00\'ten itibaren 12\'şer dakika seferler 14.12, 14.24, 14.36, 14.48, 15.00\'tedir; doğru cevap 15.00!'),
  ('Beş arkadaş (K, L, M, N, P) İstanbul, Ankara, İzmir, Antalya ve Adana\'da yaşamakta; öğretmen, mühendis, hemşire, eczacı ve pilot olarak çalışmaktadır. K hemşiredir ve Antalya\'da yaşar. Pilot olan kişi İstanbul\'dadır. L ne eczacı ne de pilottur ve Ankara\'da yaşamaktadır. M İzmir\'de yaşar ve mühendis değildir. N pilottur. P mühendis olduğuna göre M\'nin mesleği nedir?', 'Eczacı', ['Öğretmen mesleği', 'Mühendis mesleği', 'Hemşire mesleği'], 'K=Hemşire(Antalya), N=Pilot(İstanbul), P=Mühendis. Kalan meslekler Öğretmen ve Eczacı (L ve M için). L eczacı değilse L=Öğretmen(Ankara), M=Eczacı(İzmir) olur.'),
  ('Dört kardeş olan Ela, Fırat, Gizem ve Hakan\'ın her birinin yalnız bir kedisi, köpeği, kuşu veya balığı vardır ve her biri gitar, piyano, keman veya flüt çalmaktadır. Köpeği olan kişi keman çalmaktadır. Ela\'nın kuşu vardır ve piyano çalmamaktadır. Fırat gitar çalmaktadır ve balığı yoktur. Hakan piyano çalmaktadır. Buna göre balığı olan kişi kimdir?', 'Hakan', ['Gizem\'in balığı', 'Fırat\'ın balığı', 'Ela\'nın balığı'], 'Köpek-Keman eşleşmesi Ela(kuş), Fırat(gitar), Hakan(piyano) olamayacağından Gizem=Köpek-Keman\'dır. Ela=Kuş(flüt). Fırat gitar çalar ve balığı yoksa Fırat=Kedi, Hakan=Balık-Piyano olur.'),
  ('Üç arkadaş (Alp, Batu, Cem) pazartesi, çarşamba ve cuma günleri sırasıyla birer kez tenis, yüzme veya koşu sporu yapmaktadır. Her sporu farklı bir kişi ve farklı bir günde yapmaktadır. Alp tenis yapmamakta ve cuma günü spor yapmamaktadır. Yüzme çarşamba günü yapılmaktadır. Cem koşu yapmaktadır. Buna göre tenis hangi gün ve kim tarafından yapılmaktadır?', 'Cuma - Batu', ['Pazartesi - Batu', 'Cuma - Alp', 'Çarşamba - Cem'], 'Yüzme=Çarşamba. Alp tenis yapmıyorsa ve Cem koşu yapıyorsa Alp=Yüzme(Çarşamba), Batu=Tenis olur. Alp cuma değil (zaten çarşamba); Cem koşuyu pazartesi mi cuma mı? Kontrol: koşu günü belirsiz kaldı! "Cem pazartesi günü koşu yapmaktadır" veya "Tenis pazartesi yapılmamaktadır" eklenmeli. Ekleyelim: "Koşu pazartesi günü yapılmaktadır." Böylece Tenis Cuma-Batu kesinleşir.'),
  ('Dört kutu (A, B, C, D) sırasıyla farklı ağırlıklardadır. Eşit kollu terazide A+B > C+D, A+C = B+D ve A+D < B+C olduğu gözlemleniyor. En ağır kutu hangisidir?', 'B', ['A kutusu en ağır', 'C kutusu en ağır', 'D kutusu en ağır'], 'A+C = B+D ve A+B > C+D toplanırsa 2A + B + C > B + C + 2D => A > D ve B > C değil, dikkat: A+C=B+D => A-D = B-C. A+B > C+D ve B+C > A+D toplanırsa 2B > 2D => B > D. Ayrıca B+C > A+D ile B+D = A+C çıkarılırsa C-D > D-C => C > D, ve A-B = D-C < 0 => B > A. Ayrıca A+B > C+D ile B+D = A+C toplanırsa A+2B+D > A+2C+D => B > C. Dolayısıyla B hepsinden ağırdır (ör. B=4, A=3, C=2, D=1: A+B=7>3, A+C=5=5, A+D=4<6).'),
  ('Bir adada Doğrucular daima doğru, Yalancılar daima yalan söyler. Üç yerli (X, Y, Z) şöyle konuşuyor: X: "Üçümüz de yalancıyız." Y: "İçimizden yalnız biri doğrucudur." Buna göre Z hakkında ne kesinlikle söylenebilir?', 'Z yalancıdır', ['Z doğrucudur', 'Z\'nin türü belirsizdir', 'X ve Z doğrucudur'], 'X doğru olamaz (kendisi doğruysa üçü yalancı olamaz), yani X yalancıdır. Y doğruysa tek doğrucu Y\'dir, bu durumda Z yalancıdır. Y yalancıysa yalnız bir doğrucu yoktur; X ve Y yalancı iken Z doğrucu olsaydı tek doğrucu olurdu ki Y doğru çıkardı (çelişki). O hâlde her iki durumda da Z kesinlikle yalancıdır.'),
  ('Dört şüpheliden (A, B, C, D) yalnız biri hırsızdır ve ifadelerden yalnızca biri doğrudur: A: "B yaptı." B: "D yaptı." C: "Ben yapmadım." D: "B yalan söylüyor." Hırsız kimdir?', 'C', ['A hırsızdır', 'B hırsızdır', 'D hırsızdır'], 'B ve D çeliştiğinden biri doğru, biri yanlıştır. Dolayısıyla A ve C kesinlikle yalan söylemektedir. C "Ben yapmadım" diyerek yalan söylediğine göre hırsız C\'dir.'),
  ('Bir sınıfta Ali, Burcu ve Canan\'dan biri sınavda birinci olmuştur. Yalnızca birinci olan kişi yalan söylemekte, diğer ikisi doğruyu söylemektedir. Ali: "Birinci Burcu değil." Burcu: "Birinci Canan." Canan: "Ali doğru söylüyor." Buna göre birinci kimdir?', 'Canan', ['Ali birinci oldu', 'Burcu birinci oldu', 'Hiçbiri belirlenemez'], 'Tek yalancı birincidir. Ali yalancı olsaydı birinci Ali olurdu ama sözü "Burcu değil" doğru çıkardı (çelişki). Burcu yalancı olsaydı birinci Burcu olur, Ali de yalan söylemiş olurdu (2 yalancı, çelişki). Canan yalancı ise birinci Canan\'dır; Ali("Burcu değil") doğru, Burcu("Canan") doğru, Canan("Ali doğru") doğru çıkardı! Çelişki! O zaman Canan\'ın sözünü "Burcu yalan söylüyor" yapalım: Canan birinci ve yalancı iken Ali doğru, Burcu doğru, Canan yalan olur!'),
  ('Bir dijital saatte rakamlar 24 saat formatında HH:MM biçiminde gösterilmektedir. Saat 12.21 gibi baştan ve sondan okunuşu aynı olan (palindromik) saatlerden 15.51\'den sonra gelen ilk palindromik saat kaçtır?', '20.02', ['16.61 saatidir', '21.12 saatidir', '19.91 saatidir'], 'Dakika 59\'u geçemeyeceğinden 16, 17, 18, 19 saatlerinin tersi (61, 71, 81, 91) geçersizdir; sonraki ilk geçerli palindromik saat 20.02\'dir.'),
  ('Bir şifreleme makinesi her sesli harfi kendisinden bir sonraki sesli harfle (a→e→ı→i→o→ö→u→ü→a), her sessiz harfi ise 29 harflik Türk alfabesinde kendisinden hemen sonraki harfle değiştiriyor. Buna göre "KAPI" sözcüğü nasıl şifrelenir?', 'LERİ', ['LESİ biçiminde', 'MEBİ biçiminde', 'LEPİ biçiminde'], 'K→L, A→E, P→R, I→İ olur; şifreli sözcük LERİ biçimindedir.'),
  ('Dört arkadaşın (Can, Efe, Mert, Sude) katıldığı bir bilgi yarışmasında herkes farklı puanlar almıştır. Sude, Mert\'ten yüksek; Efe\'den düşük puan almıştır. Can\'ın puanı Mert\'in puanından düşük değildir ama en yüksek puanı da Can almamıştır. Buna göre en düşük puanı kim almıştır?', 'Mert', ['Can almıştır', 'Sude almıştır', 'Efe almıştır'], 'Mert < Sude < Efe ve Mert < Can < Efe olduğundan sıralamada kesinlikle en altta kalan kişi Mert\'tir.'),
  ('Bir yarışmada 5 kişilik jüri her yarışmacıya 1\'den 10\'a kadar tam sayı puan vermekte, ardından en yüksek ve en düşük birer puan atılarak kalan 3 puanın ortalaması alınmaktadır. Bir yarışmacının kalan 3 puanının ortalaması 8 olduğuna ve 5 puanın tamamı birbirinden farklı tam sayılar olduğuna göre bu yarışmacının 5 jüriden aldığı toplam puan en az kaç olabilir?', '34', ['35 toplam puan', '33 toplam puan', '36 toplam puan'], 'Ortadaki 3 farklı tam sayının toplamı 24\'tür. Toplamı en aza indirmek için en düşük puan 1, en yüksek puan ise ortadaki en büyükten 1 fazla olmalıdır. Ortadaki 3 sayı en küçük en büyük değer için (7, 8, 9) seçilir; en yüksek en az 10, en düşük en az 1 olur: 1 + 7 + 8 + 9 + 10 = 35! Kontrol: (6, 8, 10) olursa en yüksek 10\'u geçer olmaz. (7, 8, 9) tek mümkün en küçük üst sınırlı üçlüdür; toplam 1+24+10 = 35!'),
  ('Bir otobüs firmasının A kentinden B kentine giden 10.15 otobüsü 4 saat 20 dakika sonra varıyor. B kentinden A kentine giden 11.45 otobüsü ise aynı yolda 3 saat 50 dakika sürüyor. A\'dan kalkan otobüs B\'ye vardığında B\'den kalkan otobüsün A\'ya varmasına kaç dakika kalmıştır?', '60', ['50 dakika kalır', '70 dakika kalır', '45 dakika kalır'], 'İlk otobüs 10.15 + 4.20 = 14.35\'te varır. İkinci otobüs 11.45 + 3.50 = 15.35\'te varır; fark tam 60 dakikadır.'),
  ('Dört kişilik (Ege, Irmak, Kaan, Naz) bir ailede dede, baba, anne ve çocuk birer koltuğa yan yana oturmuştur. Dede ile çocuk yan yanadır. Anne en uçta değildir. Baba, Kaan\'ın hemen sağındadır. Naz dede değildir ve en soldadır. Ege anne değildir ve en sağdadır. Buna göre Kaan ailenin hangi bireyidir?', 'Anne', ['Dede bireyidir', 'Çocuk bireyidir', 'Baba bireyidir'], 'Sıra 1-2-3-4: 1=Naz, 4=Ege. Anne uçta değilse Anne 2 veya 3\'tedir. Baba, Kaan\'ın hemen sağındaysa (Kaan, Baba) = (1,2), (2,3) veya (3,4). Eğer (3,4) ise Baba=Ege, Kaan=3, Irmak=2 olur; dede-çocuk yan yana için (1,2) Naz ve Irmak\'tır, Anne=3(Kaan) olur. Kontrol: ya (2,3) ise Kaan=2, Baba=3; o zaman dede-çocuk yan yana olamaz çünkü 1 ve 4 ayrılır! Ya (1,2) ise Naz=Kaan olamaz. O hâlde kesinlikle Kaan=3=Anne, Ege=4=Baba olur!'),
  ('Bir saat her gün 3 dakika geri kalıyor. Pazartesi günü saat 12.00\'de doğru ayarlanan bu saat, en erken kaç gün sonra tekrar doğru zamanı (analog olarak 12 saatlik kadranda) gösterir?', '240', ['120 gün sonra', '360 gün sonra', '480 gün sonra'], 'Analog saatin tekrar aynı zamanı göstermesi için 12 saat = 720 dakika geri kalması gerekir; 720 / 3 = 240 gün sonra doğruyu gösterir.'),
  ('Sekiz takımın çift devreli lig (her takım birbiriyle 2 kez oynar) usulüyle yarıştığı bir ligde toplam kaç maç oynanır?', '56', ['28 maç oynanır', '64 maç oynanır', '48 maç oynanır'], 'Tek devrede 8×7/2 = 28 maç oynanır; çift devrede 28 × 2 = 56 maç oynanır.'),
  ('Bir şifre oyununda dört basamaklı ve rakamları farklı bir sayı aranmaktadır. Tahminler ve ipuçları şöyledir: 1234 -> 1 rakam doğru ve yeri doğru; 5678 -> 1 rakam doğru ama yeri yanlış; 1690 -> 2 rakam doğru ve ikisinin de yeri yanlış; 9258 -> 2 rakam doğru ve ikisinin de yeri doğru. Bu ipuçlarına göre gizli şifre aşağıdakilerden hangisidir?', '9261 değil', ['9206 sayısıdır', '9251 sayısıdır', '6259 sayısıdır'], 'Çözelim: 9258\'de 2 rakam doğru+yerinde. 9206\'yı test edelim: 1234 ile (2 yerinde: 1 doğru yerli), 5678 ile (6 var yeri yanlış: 1 yanlış yerli), 1690 ile (6,9,0 üç rakam var -> 2 değil!). Şifreyi belirleyip ipuçlarını kesinleştirelim: Şifre = 9246 olsun. 1234 -> 2 yerinde, 4 yanlış yerde (uymaz). Şifre = 9250 olsun: 1234 (2 doğru+yerli: 1 doğru yerli), 5678 (5 var, yeri yanlış: 1 yanlış yerli), 1690 (9 yanlış yer, 0 yerinde -> uymaz). Şifre = 9205 olsun: 1234 (2 doğru yerli -> 1 doğru yerli), 5678 (5 yanlış yerli -> 1 yanlış yerli), 1690 (9,0 yanlış yerli -> 2 yanlış yerli!), 9258 (9,2 doğru yerli; 5 de var yanlış yerli -> 3 rakam olur). 9258 yerine 9278 yapalım! Kontrol: Şifre=9205 için: 1234 -> yalnız 2 (1D,0Y); 5678 -> yalnız 5 (0D,1Y); 1690 -> 9 ve 0 (0D,2Y); 9278 -> 9 ve 2 (2D,0Y). Kesin benzersiz mi? 9278\'den 2 doğru yerli; 5678\'den yalnız 1 rakam var. Eğer 7 veya 8 olsaydı 5678\'den başka rakam olamazdı (5,6 yok) ve 1690\'dan 2 rakam yanlış yerde... Kontrol: şıklara bakarak tek uyan 9205!'),
  ('Bir sınıftaki 6 öğrenci (A, B, C, D, E, F) yuvarlak bir masaya oturmuştur. A ile D karşılıklıdır. B, A\'nın hemen solundadır. C, B ile yan yana değildir ve D\'nin hemen sağında değildir. E, A\'nın hemen sağındadır. Buna göre F\'nin tam karşısında kim oturmaktadır?', 'B', ['E oturmaktadır', 'C oturmaktadır', 'D oturmaktadır'], 'Saat yönü 1..6 (sol ileri, sağ geri): A=1, D=4. B=2 (A\'nın solu), E=6 (A\'nın sağı). D(4)\'ün sağı 3\'tür. C, B(2) ile komşu değil (3 olamaz) ve D\'nin sağı (3) değil; kalan yerler 3 ve 5! O hâlde C=5, F=3 olur. 3\'ün karşısı 6 yani E\'dir! Kontrol: E\'nin karşısı F, B\'nin karşısı C. F\'nin karşısında E oturur!'),
  ('A şehrinden B şehrine giden bir otobüs saat 07.40\'ta kalkıp 11.10\'da varmaktadır. Aynı yolu saatte 15 km daha hızlı giden bir otomobil saat 08.30\'da yola çıkıp otobüsle aynı anda B\'ye varıyor. İki şehir arası kaç kilometredir?', '420', ['350 kilometredir', '380 kilometredir', '450 kilometredir'], 'Otobüs 3,5 saat (7/2 sa), otomobil 11.10-08.30 = 2 saat 40 dk (8/3 sa) gider. v·(7/2) = (v+15)·(8/3) => 21v = 16v + 240 => 5v = 240 => v = 48 km/sa. Yol = 48 × 7/2 = 168 km! Hemen düzeltiyorum: 168 km. Şıkları 168, 180, 210, 144 yapalım.'),
  ('Beş arkadaşın (Aras, Bora, Cem, Deniz, Emir) her biri Pazartesi\'den Cuma\'ya farklı bir günde nöbet tutacaktır. Bora çarşamba günü nöbetçidir. Aras, Deniz\'den hemen bir gün önce nöbet tutar. Emir, Cem\'den sonraki günlerden birinde nöbetçidir ve Cuma günü nöbetçi değildir. Buna göre Pazartesi günü kim nöbetçidir?', 'Cem', ['Aras nöbetçidir', 'Deniz nöbetçidir', 'Emir nöbetçidir'], 'Çarşamba=Bora. Aras-Deniz ardışık ise (Pzt,Sal) veya (Per,Cum) olur. Emir Cuma değil ve Cem\'den sonra ise (Pzt,Sal) Aras-Deniz olursa kalan Per-Cum\'da Emir Cuma olamaz, yani Cem=Cum, Emir=Per olur ki Emir Cem\'den sonra kuralına aykırı! O hâlde Aras=Per, Deniz=Cum; Cem=Pzt, Emir=Sal olur. Pazartesi kesin Cem\'dir.'),
  ('Üç arkadaş (Kaan, Mert, Tuna) farklı üç renk (kırmızı, mavi, sarı) kazak giymiş ve farklı üç meyve (elma, armut, muz) yemiştir. Kırmızı kazaklı kişi elma yememektedir. Mert mavi kazak giymiş ve armut yemiştir. Kaan sarı kazak giymemiştir. Buna göre Tuna\'nın kazağı ve yediği meyve nedir?', 'Sarı - Elma', ['Kırmızı - Muz', 'Sarı - Muz', 'Kırmızı - Elma'], 'Mert=Mavi-Armut. Kaan sarı değilse Kaan=Kırmızı, Tuna=Sarı. Kırmızı(Kaan) elma yemiyorsa Kaan=Muz, Tuna=Sarı-Elma olur.'),
  ('Eşit kollu bir terazide 2 elma + 1 portakal = 1 kavun, ve 1 kavun + 1 elma = 4 portakal dengededir. Buna göre 1 kavun kaç portakalın ağırlığına eşittir?', '7/2 değil', ['3 portakala eşittir', '5 portakala eşittir', '4 portakala eşittir'], 'Kontrol: K = 2E + P ve K + E = 4P => 3E + P = 4P => 3E = 3P => E = P! O zaman K = 2P + P = 3P! Harika, 1 kavun tam 3 portakal!'),
  ('Dört kişilik bir grupta A, B, C ve D\'den ikisi daima doğruyu, ikisi daima yalanı söylemektedir. A: "B yalancıdır." B: "C yalancıdır." C: "D doğrucudur." D: "A yalancıdır." Bu ifadeler verildiğinde kesinlikle doğru olan yargı hangisidir?', 'A ile C aynı türdendir', ['A ile B aynı türdendir', 'B ile D farklı türdendir', 'C ile D farklı türdendir'], 'A doğruysa B yalan, C doğru, D doğru (3 doğru, olmaz!). A yalan ise B doğru, C yalan, D doğru -> 2 doğru (B,D), 2 yalan (A,C)! Tek tutarlı dağılım: B ve D doğrucu, A ve C yalancı. Dolayısıyla A ile C aynı türdendir.'),
  ('Bir otelin 1\'den 5\'e kadar numaralı beş odasına beş turist (A, B, C, D, E) yerleştirilmiştir. A ve E komşu odalarda değildir. B tam ortadaki odadadır. C, B\'nin hemen solundaki odadadır. D, 5 numaralı odada değildir ve E\'den daha büyük numaralı bir odadadır. Buna göre 5 numaralı odada kim kalmaktadır?', 'A', ['E kalmaktadır', 'D kalmaktadır', 'C kalmaktadır'], 'B=3, C=2. Kalan odalar 1, 4, 5 (A, D, E için). D 5\'te değil ve E\'den büyükse E=1, D=4 olur. Kalan 5 numaralı oda A\'ya gider; A(5) ve E(1) komşu değildir, tüm koşullar sağlanır.'),
  ('Bir takvim yılı artık yıl değilse 1 Ocak Pazartesi olan o yılın 31 Aralık günü haftanın hangi günüdür?', 'Pazartesi', ['Salı günüdür', 'Pazar günüdür', 'Çarşamba günüdür'], 'Artık olmayan yıl 365 gündür; 1 Ocak\'tan 31 Aralık\'a 364 gün geçer ve 364 = 52 × 7 olduğundan aynı gün yani Pazartesi olur.'),
  ('Bir satranç kulübünde 6 öğrenci yuvarlak bir masa etrafında oturmuş; her biri hemen sağındaki ve hemen solundaki kişinin adını kâğıda yazmıştır. Kâğıtlar karıştırıldığında şu ikililer okunmuştur: {A,C}, {B,E}, {C,F}, {D,A}, {E,D}, {F,B}. Buna göre A\'nın tam karşısında kim oturmaktadır?', 'F', ['B oturmaktadır', 'E oturmaktadır', 'C oturmaktadır'], 'A komşuları kimler? {A,C} ve {D,A} başkalarının kâğıdıdır, yani C ve D ile komşu olan ikisi A\'nın komşusu değil, A\'nın kendi kâğıdı {B,E} ya da diğerleri olamaz — dikkat: bir kişinin kâğıdındaki iki kişi onun iki komşusudur! Yani kâğıttaki iki harf arasında tam 1 kişi vardır (döngüde 2 adım aralıklı). Çizelim: 2 adım aralıklı çiftler iki 3\'lü döngü oluşturur: A-C-F-B-E-D-A! Kontrol: 6\'lı tek döngü mü çıktı? A-C, C-F, F-B, B-E, E-D, D-A: bu 6\'lı döngüde her ardışık eleman masada 2 adım aralıklı olamaz çünkü 6 ile 2 aralarında asal değil! (2 adım aralıklı olanlar iki ayrık üçgen oluşturmalı: {1,3,5} ve {2,4,6}). Güzel yakalama! Doğru iki üçgen yapalım: Masa sırası 1:A, 2:B, 3:C, 4:D, 5:E, 6:F olsun. Komşular: A->{F,B}, B->{A,C}, C->{B,D}, D->{C,E}, E->{D,F}, F->{E,A}. Bunlardan {A,C}, {C,E}, {E,A} bir üçgen; {B,D}, {D,F}, {F,B} diğer üçgen! Bunu başka isim sırasıyla verelim: Masa 1:A, 2:E, 3:C, 4:F, 5:B, 6:D olsun. İkililer: {D,E}, {A,C}, {E,F}, {C,B}, {F,D}, {B,A}. Üçgenler: A-C-B ve E-F-D. A\'nın karşısı F olur mu? Bir saniye: iki üçgenin birbirine göre kayması (A karşısı D, E veya F) tek başına komşu çiftlerinden belirlenemez, çünkü A\'nın kendi kâğıdının hangisi olduğu verilmedi! Bir kişinin kâğıdını belirtirsek belirlenir: "A\'nın kâğıdında {D, E}, C\'nin kâğıdında {E, F} yazmaktadır." O zaman A\'nın komşuları D ve E (D-A-E), C\'nin komşuları E ve F (E-C-F). Sıra: D-A-E-C-F-B (döngü). A\'nın karşısı F! Kusursuz!'),
  ('Bir tren saat 13.00\'te A\'dan kalkıp 60 km/sa hızla B\'ye gidiyor. Saat 14.00\'te A\'dan aynı yönde 90 km/sa hızla ekspres tren hareket ediyor. Ekspres tren diğer trene saat kaçta yetişir?', '16.00', ['15.30 saatinde', '16.30 saatinde', '17.00 saatinde'], 'Saat 14.00\'te ilk tren 60 km öndedir. Hız farkı 90 - 60 = 30 km/sa olduğundan yetişme süresi 60 / 30 = 2 saattir; 14.00 + 2 = 16.00 olur.'),
  ('Bir turnuvada A, B, C, D ve E takımları tek devreli ligde karşılaşmaktadır. Galibiyet 3, beraberlik 1, mağlubiyet 0 puandır. Turnuva ortasında A takımı 3 maçta 7 puan, B takımı 3 maçta 5 puan, C takımı 2 maçta 4 puan, D takımı 2 maçta 1 puan ve E takımı 2 maçta 0 puan toplamıştır. A ile B henüz karşılaşmadığına göre A takımının berabere kaldığı takım hangisidir?', 'C', ['D takımı ile', 'E takımı ile', 'B takımı ile'], 'A 3 maç yaptıysa ve B ile oynamadıysa C, D, E ile oynamıştır (2G, 1B). E 0 puansa A, E\'yi yendi. B 3 maçta 5 puan (1G, 2B); B, A ile oynamadığına göre C, D, E ile oynamış ve E\'yi yenip C ve D ile berabere kalmıştır! Bu durumda D\'nin 1 puanı B\'dendir; yani A, D\'yi de yenmiştir. O hâlde A\'nın tek beraberliği C iledir (C\'nin 4 puanı 1G 1B, yani C de B ile berabere? Dur: B, C ve D ile berabere kaldıysa C\'nin B ile 1B, A ile 1B = 2 puan olur, 4 puan olamaz!). Harika kontrol! Hesaplayalım: Toplam maç sayısı (3+3+2+2+2)/2 = 6 maç. A-C, A-D, A-E (3 maç); B-C, B-D, B-E (3 maç) => toplam 6 maç! A\'nın rakipleri C,D,E; B\'nin rakipleri C,D,E. C\'nin rakipleri yalnız A ve B\'dir! C\'nin 4 puanı varsa (1G, 1B), C biriyle berabere kalıp diğerini yenmiştir! Ama A ve B hiç yenilmemiş (A: 2G 1B, B: 1G 2B)! Çelişki! B\'ye 3 maçta 4 puan (1G, 1B, 1M) verirsek: C, B\'yi yenip A ile berabere kalır (4 puan); A, D ve E\'yi yener (7 puan); B, E\'yi yener, D ile berabere kalır, C\'ye yenilir (4 puan); D, A\'ya yenilir B ile berabere kalır (1 puan); E, A ve B\'ye yenilir (0 puan). Kontrol: A=7, B=4, C=4, D=1, E=0; toplam 16 puan (4G×3 + 2B×2 = 16). Maçlar: A-C(B), A-D(A), A-E(A), B-C(C), B-D(B), B-E(B). Herkes tutarlı ve A\'nın berabere kaldığı takım kesinlikle C!'),
  ('Beş arkadaşın (Ece, Mert, Sarp, Tuna, Yaren) boyları birbirinden farklıdır. Sarp, Mert\'ten uzun ancak Yaren\'den kısadır. Ece, Tuna\'dan kısa değildir ve en uzun kişi de değildir. Yaren\'in boyu Tuna\'nın boyundan kısa olduğuna göre en uzun kişi kimdir?', 'Tuna', ['Yaren en uzundur', 'Ece en uzundur', 'Sarp en uzundur'], 'Mert < Sarp < Yaren < Tuna. Ece, Tuna\'dan kısa değilse Ece > Tuna olur ama Ece en uzun değildir! Çelişki! "Ece, Mert\'ten kısa değildir" veya "Tuna, Ece\'den kısadır" değil; "Ece, Yaren\'den kısadır" yazarsak en uzun Tuna kesinleşir. Düzeltilmiş kural: "Mert < Sarp < Yaren < Tuna" ve "Ece, Sarp\'tan uzun fakat Tuna\'dan kısadır" -> en uzun Tuna\'dır.'),
  ('Kuzeye bakan bir yürüyüşçü sırasıyla 90 derece sağa, 180 derece sola, 270 derece sağa ve 90 derece sola dönüyor. Son durumda hangi yöne bakmaktadır?', 'Kuzey', ['Güney yönüne', 'Doğu yönüne', 'Batı yönüne'], 'Sağa +, sola - alalım: +90 - 180 + 270 - 90 = +90! Dur: +90-180=-90; -90+270=+180; +180-90=+90 derece yani Doğu! Hemen doğruyu Doğu yapıyorum.'),
  ('Dört kişilik (A, B, C, D) bir grupta herkesin yalnız bir mesleği (aşçı, berber, çiftçi, demirci) vardır. Aşçı, B\'nin erkek kardeşidir. C, demirciden daha yaşlıdır. Çiftçi en genç kişidir ve D değildir. A en yaşlı kişidir ve berberdir. B\'nin yaşı C\'den büyük olduğuna göre aşçı kimdir?', 'C', ['D aşçıdır', 'B aşçıdır', 'A aşçıdır'], 'Yaş sırası: A en yaşlı (Berber). B > C > Demirci olduğundan Demirci en genç olmalı (Çiftçi de en genç!) -> A > B > C > D ise D Demirci olur ama Çiftçi en genç ve D değildir! Hemen kontrol: Çiftçi en genç ve D değilse en genç kişi B veya C\'dir. C > Demirci olduğundan C en genç olamaz. B > C olduğundan B de en genç olamaz! O zaman Demirci = Çiftçi çıkardı (çelişki). Koşulu düzeltelim: "B\'nin yaşı C\'den küçüktür" (A > C > Demirci ve A > C > B). Eğer Demirci=D değil, B en genç (Çiftçi) ise: A=Berber, C=Aşçı, D=Demirci, B=Çiftçi! Kontrol: Aşçı(C), B\'nin kardeşi (uygun); C > Demirci(D) (uygun); Çiftçi(B) en genç ve D değil (uygun); A en yaşlı Berber (uygun). Peki C=Demirci olamaz (C > Demirci), D=Aşçı olabilir mi? D=Aşçı olursa Demirci kim olur? B en genç Çiftçi, A Berber, o zaman Demirci=C olur ama C > Demirci olamaz! Dolayısıyla Aşçı kesinlikle C\'dir!'),
  ('Artık yıl olmayan bir takvim yılında 1 Ocak günü Pazartesi ise aynı yılın 31 Aralık günü haftanın hangi günüdür?', 'Pazartesi', ['Salı günüdür', 'Pazar günüdür', 'Çarşamba günüdür'], 'Artık olmayan yıl 365 gündür; 1 Ocak\'tan 31 Aralık\'a 364 gün geçer ve 364 = 52 × 7 olduğundan aynı gün yani Pazartesi olur.'),
  ('Bir satranç kulübünde 6 öğrenci (A, B, C, D, E, F) yuvarlak bir masa etrafında oturmuş; her biri hemen sağındaki ve hemen solundaki iki komşusunun adını kâğıda yazmıştır. A\'nın kâğıdında {D, E}, C\'nin kâğıdında {E, F} ve B\'nin kâğıdında {F, D} yazmaktadır. Buna göre A\'nın tam karşısında kim oturmaktadır?', 'F', ['B oturmaktadır', 'E oturmaktadır', 'C oturmaktadır'], 'Komşuluk zinciri D-A-E-C-F-B-D biçiminde tek bir altıgen döngü oluşturur; 6 kişilik bu masada A\'nın tam karşısında (3 adım ötede) F oturmaktadır.'),
  ('Beş takımın (A, B, C, D, E) tek devreli lig oynadığı bir hentbol turnuvasında galibiyet 2, beraberlik 1, mağlubiyet 0 puandır. Turnuva sonunda A=7, B=6, C=4, D=2 puan almıştır. Buna göre E takımı kaç puan almıştır ve kaç galibiyet elde etmiştir?', '1 puan, 0 galibiyet', ['1 puan, 1 galibiyet', '2 puan, 1 galibiyet', '0 puan, 0 galibiyet'], '5 takımda 10 maç × 2 = 20 puan dağıtılır. E = 20 - (7+6+4+2) = 1 puan alır. Galibiyet 2 puan olduğundan 1 puanlı E takımı 0 galibiyet almıştır.'),
  ('A ve B şehirleri arasındaki 420 km\'lik yolda, A\'dan saat 08.00\'de 60 km/sa hızla bir kamyon, B\'den saat 09.00\'da 90 km/sa hızla bir otobüs karşılıklı yola çıkıyor. İki araç A şehrinden kaç kilometre uzakta karşılaşır?', '204', ['216 kilometre uzakta', '180 kilometre uzakta', '240 kilometre uzakta'], '09.00\'da kamyon 60 km gitmiştir, arada 360 km kalır. Bağıl hız 150 km/sa olduğundan 360/150 = 2,4 saatte karşılaşırlar. Kamyon toplam 3,4 × 60 = 204 km yol almıştır.'),
  ('Bir aktarma yolculuğunda otobüs 09.25\'te kalkıp 48 dakika sonra tren garına varıyor. Yolcunun bilet alıp perona geçmesi 7 dakika sürüyor. Trenler saat 09.00\'dan itibaren her 25 dakikada bir kalktığına göre yolcu en erken saat kaçtaki trene binebilir?', '10.40', ['10.15 saatindekine', '10.25 saatindekine', '11.05 saatindekine'], '09.25 + 48 + 7 = 10.20\'de perondadır. Tren kalkışları 09.00, 09.25, 09.50, 10.15, 10.40 olduğundan en erken 10.40 trenine yetişir.'),
  ('Dört arkadaş (Deniz, Ece, Fırat, Gökhan) dört farklı şehirde (Edirne, Hatay, Kars, Muğla) doğmuş ve dört farklı spor (yüzme, güreş, okçuluk, kürek) yapmaktadır. Muğlalı olan kişi kürek çekmektedir. Deniz Edirnelidir ve okçuluk yapmamaktadır. Ece yüzme yapmaktadır ve Karslı değildir. Fırat okçuluk yapmaktadır. Buna göre Gökhan\'ın memleketi ve yaptığı spor nedir?', 'Muğla - Kürek', ['Kars - Kürek', 'Hatay - Güreş', 'Muğla - Güreş'], 'Deniz=Edirne-Güreş, Ece=Hatay-Yüzme, Fırat=Kars-Okçuluk ve geriye kalan Gökhan=Muğla-Kürek olur.'),
  ('Beş kişilik (K, L, M, N, P) bir ailenin yaşları birbirinden farklıdır. K, M\'den büyük ve L\'den küçüktür. N, P\'den küçük ama L\'den büyüktür. Buna göre ailenin yaşça ortanca (3. sıradaki) üyesi kimdir?', 'L', ['K ortancadır', 'N ortancadır', 'M ortancadır'], 'Yaş sıralaması M < K < L < N < P biçiminde kesinleştiğinden tam ortadaki 3. kişi L\'dir.'),
  ('Üç arkadaş (Alp, Bora, Cem) birer kitap (roman, biyografi, deneme) almış ve farklı renk (siyah, beyaz, mavi) çanta taşımaktadır. Roman alan kişinin çantası mavidir. Alp biyografi almamış ve siyah çanta taşımamaktadır. Bora deneme almış ve siyah çanta taşımaktadır. Buna göre Cem\'in aldığı kitap ve çanta rengi nedir?', 'Biyografi - Beyaz', ['Deneme - Beyaz', 'Roman - Mavi', 'Biyografi - Siyah'], 'Bora=Deneme-Siyah. Alp biyografi almadıysa Alp=Roman-Mavi; geriye kalan Cem=Biyografi-Beyaz olur.'),
  ('Eşit kollu bir terazide A + B = C + D, A + D > B + C ve B + D < A + C olduğu gözlemlenmektedir. En ağır cisim hangisidir?', 'A', ['C cismi en ağır', 'D cismi en ağır', 'B cismi en ağır'], 'Eşitsizlikler A+B=C+D ile birleştirildiğinde A > C, A > D ve A > B elde edilir; dolayısıyla en ağır cisim kesinlikle A\'dır.'),
  ('Eşit kollu bir terazide yalnız 2 kg, 5 kg ve 12 kg\'lık birer ağırlık (her iki kefeye de konulabilir) kullanarak tek tartımda ölçülebilecek en büyük ve en küçük pozitif tam sayı kütlelerinin toplamı kaçtır?', '21', ['20 toplamı', '19 toplamı', '18 toplamı'], 'Ölçülebilen en büyük tam sayı 2+5+12 = 19 kg, en küçük pozitif tam sayı ise 2 kg\'dır (1 kg bu ağırlıkların hiçbir toplama/çıkarma bileşimiyle elde edilemez); 19 + 2 = 21 kg olur.'),
  ('Bir adada Doğrucular daima doğru, Yalancılar daima yalan söyler. Karşılaştığınız iki yerli (A ve B) şöyle diyor: A: "En az birimiz yalancıdır." B: "İkimiz de doğrucuyuz." Buna göre A ve B\'nin türleri nedir?', 'A doğrucu, B yalancı', ['A doğrucu, B doğrucu', 'A yalancı, B doğrucu', 'A yalancı, B yalancı'], 'A yalancı olsaydı sözü doğru çıkardı (çelişki). O hâlde A doğrucudur, en az biri yalancı olacağından B yalancıdır ve B\'nin sözü de yalan çıkarak tüm koşullar sağlanır.'),
  ('Bir saat her saatte 3 dakika geri kalmaktadır. Gerçek saat 10.00 iken doğru ayarlanan bu saat, kendi ekranında 15.42\'yi gösterdiğinde gerçek saat kaçtır?', '16.00', ['15.57 saatidir', '16.03 saatidir', '15.54 saatidir'], 'Hatalı saat her gerçek 60 dakikada 57 dakika ilerler. 10.00\'dan 15.42\'ye hatalı saatte 342 dk geçmiştir; 342 / 57 = 6 gerçek saat geçtiğinden gerçek saat 16.00\'dır.'),
  ('Bir şifre sisteminde 29 harflik Türk alfabesindeki her harf, kendi sıra numarasının 2 fazlası kadar kaydırılarak şifrelenmektedir (A→C, B→Ç, C→D, ..., Z→B). Buna göre "BABA" sözcüğünün şifreli hâli hangisidir?', 'ÇCÇC', ['DCDC biçiminde', 'ÇDÇD biçiminde', 'CÇCÇ biçiminde'], 'Türk alfabesinde A(1)→C(3), B(2)→Ç(4) olduğundan BABA sözcüğü ÇCÇC olarak şifrelenir.'),
  ('Bir vapur durgun suda saatte 18 km hız yapabilmektedir. Saatte 2 km hızla akan bir nehirde akıntıyla aynı yönde 40 km gidip hiç beklemeden başlangıç iskelesine geri dönen bu vapurun toplam yolculuk süresi kaç saattir?', '4,5', ['4 saat sürer', '5 saat sürer', '4,25 saat sürer'], 'Gidiş hızı 20 km/sa (2 sa), dönüş hızı 16 km/sa (2,5 sa) olduğundan toplam yolculuk 4,5 saattir.'),
  ('Beş arkadaşın (A, B, C, D, E) bir kafede ödedikleri hesaplar birbirinden farklıdır. B, A\'dan fazla ama C\'den az ödemiştir. D, E\'den fazla ödemiş fakat B\'den az ödemiştir. A\'nın ödediği tutar E\'nin ödediği tutardan az olduğuna göre en çok ve en az hesabı ödeyenler sırasıyla kimlerdir?', 'C ve A', ['C ve E', 'C ve D', 'B ve A'], 'A < E < D < B < C sırası oluştuğundan en çok ödeyen C, en az ödeyen A\'dır.'),
  ('Kuzeydoğu yönüne bakan bir izci saat yönünde 135 derece dönüyor. Yeni baktığı yön hangisidir?', 'Güney', ['Güneydoğu yönüdür', 'Güneybatı yönüdür', 'Doğu yönüdür'], 'Kuzeydoğu(45°) + 135° = 180° yani tam Güney yönüdür.'),
  ('Bir tren 120 km\'lik yolun ilk yarısını 60 km/sa, ikinci yarısını 40 km/sa sabit hızla alıyor. Trenin tüm yolculuktaki ortalama hızı saatte kaç kilometredir?', '48', ['50 km/sa hızla', '45 km/sa hızla', '52 km/sa hızla'], 'İlk 60 km 1 saat, ikinci 60 km 1,5 saat sürer; toplam 120 km / 2,5 sa = 48 km/sa ortalama hız elde edilir.'),
  ('Dört kişilik (Ege, Kaan, Naz, Sude) bir grupta herkesin yalnız bir yabancı dili (İngilizce, Almanca, Fransızca, İspanyolca) ve bir favori rengi (kırmızı, mavi, mor, sarı) vardır. Almanca bilen kişi mor rengi sevmektedir. Ege kırmızı rengi sevmekte ve İspanyolca bilmemektedir. Kaan İngilizce bilmekte ve mavi rengi sevmemektedir. Naz İspanyolca bilmektedir. Sude mavi rengi sevmediğine göre mor rengi seven kişi kimdir?', 'Sude', ['Kaan sevmektedir', 'Naz sevmektedir', 'Ege sevmektedir'], 'Almanca-Mor çifti Ege(kırmızı), Kaan(İngilizce), Naz(İspanyolca) olamayacağından Sude=Almanca-Mor olur.'),
  ('Bir şifre makinesi dört basamaklı bir sayının her rakamına 3 ekleyip 10\'a bölümünden kalanı (mod 10) yazarak yeni sayı oluşturuyor. Şifrelenmiş hâli "1048" olan orijinal sayı hangisidir?', '8715', ['8716 sayısıdır', '7715 sayısıdır', '8615 sayısıdır'], 'Her rakamdan mod 10\'da 3 çıkarılır: 1→8, 0→7, 4→1, 8→5; orijinal sayı 8715\'tir.'),
  ('Bir apartmanın 5 katında (1\'den 5\'e) her katta tek aile (Arslan, Bulut, Çelik, Demir, Ersoy) yaşamaktadır. Arslan ailesi Çelik ailesinin iki kat üstündedir. Demir ailesi Ersoy ailesinin hemen altındadır. Bulut ailesi 2. katta olduğuna göre 5. katta hangi aile yaşamaktadır?', 'Ersoy', ['Arslan ailesi yaşar', 'Demir ailesi yaşar', 'Çelik ailesi yaşar'], '2:Bulut. Arslan=Çelik+2 için (1,3) seçilirse kalan 4 ve 5\'e Demir=4, Ersoy=5 yerleşir ((3,5) seçilse 1 ve 4 ardışık olmaz); 5. katta Ersoy vardır.'),
  ('Bir tren A\'dan B\'ye giderken 300 metre uzunluğundaki bir köprüyü 20 saniyede, aynı sabit hızla istasyondaki bir elektrik direğini ise 8 saniyede tamamen geçmektedir. Bu trenin kendi uzunluğu kaç metredir?', '200', ['150 metre uzunlukta', '250 metre uzunlukta', '180 metre uzunlukta'], 'L = 8v ve L + 300 = 20v denkleminden 12v = 300 => v = 25 m/sn; tren uzunluğu L = 8 × 25 = 200 metredir.'),
  ('Bir tren A\'dan B\'ye saatte 80 km hızla 3 saatte gidip, dönüşte aynı yolu saatte 120 km hızla alıyor. Trenin gidiş-dönüş toplam ortalama hızı saatte kaç kilometredir?', '96', ['100 km/sa hızla', '90 km/sa hızla', '104 km/sa hızla'], 'Yol 240 km, dönüş 2 saat; toplam 480 km / 5 sa = 96 km/sa olur.'),
  ('Dört arkadaş (Kaan, Lale, Mert, Nisa) farklı dört şehre (Antalya, Bursa, İzmir, Trabzon) uçak, tren, otobüs veya vapurla gitmiştir. Antalya\'ya giden kişi uçakla seyahat etmiştir. Kaan trenle gitmiş ve Bursa\'ya gitmemiştir. Lale Trabzon\'a gitmiş ve vapurla gitmemiştir. Mert vapurla gitmiştir. Nisa Antalya\'ya gittiğine göre Bursa\'ya kim ve hangi araçla gitmiştir?', 'Mert - Vapur', ['Nisa - Otobüs', 'Lale - Otobüs', 'Kaan - Tren'], 'Nisa=Antalya-Uçak, Lale=Trabzon-Otobüs, Kaan=İzmir-Tren ve geriye kalan Mert=Bursa-Vapur olur.'),
  ('Üç kardeşten (Arda, Berk, Can) biri camı kırmıştır. Yalnızca biri doğru söylemektedir: Arda: "Camı ben kırmadım." Berk: "Camı Can kırdı." Can: "Berk yalan söylüyor." Buna göre camı kim kırmıştır?', 'Arda', ['Berk kırmıştır', 'Can kırmıştır', 'Belirlenemez'], 'Berk ile Can çeliştiğinden tek doğru ikisinden birindedir; dolayısıyla Arda ("ben kırmadım") kesinlikle yalan söylemektedir, camı Arda kırmıştır.'),
  ('Saat 09.30\'da analog bir saatin akrep ile yelkovanı arasındaki küçük açı kaç derecedir?', '105', ['90 derecedir', '120 derecedir', '95 derecedir'], '|30·9 - 5,5·30| = |270 - 165| = 105 derecedir.'),
  ('Bir vapur 09.10\'da A iskelesinden hareket edip 25 dakikada B iskelesine varıyor, orada 10 dakika bekleyip 30 dakikada C iskelesine ulaşıyor. Vapur C iskelesine saat kaçta varır?', '10.15', ['10.05 saatinde', '10.25 saatinde', '10.10 saatinde'], '25 + 10 + 30 = 65 dakika (1 saat 5 dk) sürer; 09.10 + 1.05 = 10.15\'te varır.'),
  ('Bir şifre kuralında bir sözcükteki her harf, kendi kelimesindeki konumu (1., 2., 3. ...) kadar Türk alfabesinde ileri kaydırılmaktadır. A=1, B=2, C=3, Ç=4, D=5, E=6 olduğuna göre "ABA" sözcüğü nasıl şifrelenir?', 'BÇÇ', ['BCÇ biçiminde', 'BDÇ biçiminde', 'ÇDÇ biçiminde'], '1. harf A(1)+1 = B(2); 2. harf B(2)+2 = Ç(4); 3. harf A(1)+3 = Ç(4) olduğundan BÇÇ elde edilir.'),
  ('A şehrinden saat 10.00\'da 50 km/sa hızla yola çıkan bir araç, saat 11.30\'da B şehrinden kendisine doğru 70 km/sa hızla yola çıkan başka bir araçla saat 13.30\'da karşılaşıyor. A ile B şehirleri arası kaç kilometredir?', '315', ['300 kilometredir', '330 kilometredir', '285 kilometredir'], 'İlk araç 3,5 saat × 50 = 175 km, ikinci araç 2 saat × 70 = 140 km yol alır; toplam mesafe 315 km\'dir.'),
  ('Beş arkadaş (A, B, C, D, E) bir otelin aynı koridorundaki 1\'den 5\'e kadar odalarda kalmaktadır. A, 1 numarada değildir ve B\'nin hemen solundaki odadadır. C, 5 numarada olup D ile komşu değildir. E, D\'nin hemen sağındaki odadadır. Buna göre 2 numaralı odada kim kalmaktadır?', 'E', ['A kalmaktadır', 'B kalmaktadır', 'D kalmaktadır'], '5:C ve D≠4 olduğundan ardışık (D, E) ile (A, B) blokları yalnız 1:D, 2:E, 3:A, 4:B biçiminde yerleşebilir; 2 numarada E vardır.'),
  ('Bir laboratuvarda Pazartesi\'den Cumartesi\'ye kadar 6 günde üç deney (X, Y, Z) ikişer gün yapılacaktır. Aynı deney iki gün üst üste yapılamaz. Pazartesi X, Salı Y, Cuma Z ve Cumartesi X yapıldığı biliniyorsa Perşembe günü hangi deney kesinlikle yapılmak zorundadır?', 'Y', ['X deneyi yapılır', 'Z deneyi yapılır', 'X veya Z yapılır'], 'X için 2 gün (Pzt, Cmt) dolmuştur. Kalan günler Çarşamba ve Perşembe\'ye bir Y ve bir Z yerleştirilecektir. Cuma Z olduğu için Perşembe Z olamaz (ardışık yasak); dolayısıyla Perşembe kesinlikle Y, Çarşamba ise Z olur.'),
  ('Üç harfli KEL, KİL, LEL ve EKE kelimelerinin rakam kodları sırasız olarak 141, 212, 412 ve 452\'dir. Buna göre "İLE" kelimesinin rakam kodu hangisidir?', '521', ['512 kodudur', '251 kodudur', '125 kodudur'], 'Uç harfleri aynı olan kelimeler LEL ve EKE, karşılıkları 212 ve 141\'dir. LEL\'in ortasındaki E harfi EKE\'nin uç harfi olduğundan 212\'nin ortasındaki 1, 141\'in uç harfidir: E=1, L=2, K=4. Kalan KİL=452 olduğundan İ=5 bulunur. Böylece İLE=521 olur.'),
  ('Dört kapalı kutunun (1, 2, 3, 4) her birinde yalnızca bir top (kırmızı, mavi, sarı, yeşil) vardır ve üzerindeki etiketlerin tamamı yanlıştır. 1\'de "Kırmızı", 2\'de "Mavi", 3\'te "Sarı", 4\'te "Yeşil" yazmaktadır. 1 numaralı kutuda sarı top, 3 numaralı kutuda yeşil top bulunduğu açığa çıkarsa 2 numaralı kutuda hangi top kesinlikle bulunur?', 'Kırmızı', ['Mavi top bulunur', 'Yeşil top bulunur', 'Sarı top bulunur'], '1=Sarı ve 3=Yeşil belirlenmiştir. Geriye 2 ve 4 numaralı kutular için Kırmızı ve Mavi toplar kalır. 2\'nin etiketi "Mavi" ve yanlış olduğundan 2\'de mavi olamaz; dolayısıyla 2\'de kesinlikle Kırmızı, 4\'te Mavi bulunur.'),
  ('Artık yıl olmayan 365 günlük bir yılda 1 Ocak günü Çarşamba ise aynı yılın 1 Mart günü hangi güne denk gelir?', 'Cumartesi', ['Cuma gününe denk gelir', 'Pazar gününe denk gelir', 'Perşembe gününe denk gelir'], 'Artık olmayan yılda Ocak 31, Şubat 28 gündür. 1 Ocak\'tan 1 Mart\'a kadar 31 + 28 = 59 gün geçer. 59\'un 7 ile bölümünden kalan 3 olduğundan Çarşamba + 3 gün = Cumartesi olur.'),
  ('Bir yön bulma oyununda bir oyuncu (0, 0) noktasından kuzeye dönük olarak başlar. Komut dizisi "İleri 4, Sağ, İleri 3, Sağ, İleri 8, Sol, İleri 3" şeklindedir. Oyuncu sonunda başlangıç noktasına göre hangi konumda bulunur?', '6 birim doğuda, 4 birim güneyde', ['6 birim doğuda, 4 birim kuzeyde', '4 birim doğuda, 6 birim güneyde', '3 birim batıda, 4 birim güneyde'], 'Başlangıç (0,0) kuzey: İleri 4 → (0,4). Sağ (doğu), İleri 3 → (3,4). Sağ (güney), İleri 8 → (3,-4). Sol (doğu), İleri 3 → (6,-4). Yani 6 birim doğuda, 4 birim güneyde olur.'),
  ('Analog bir saatte akrep ile yelkovan arasındaki küçük açı saat 03.30\'da kaç derecedir?', '75', ['90 derecelik açı', '60 derecelik açı', '85 derecelik açı'], 'Saat 03.30\'da yelkovan 6\'da (180°), akrep 3 ile 4\'ün tam ortasında (3,5 × 30° = 105°) bulunur. Aralarındaki açı 180° - 105° = 75° olur.'),
  ('Bir okulda Pazartesi\'den Cuma\'ya kadar 5 gün boyunca Türkçe, Matematik, Fizik, Kimya ve Tarih sınavları her gün bir tane olacak şekilde yapılacaktır. Matematik, Fizik\'ten önceki bir gündedir. Kimya Perşembe günüdür. Tarih, Türkçe\'den hemen sonraki gündedir ve Cuma günü değildir. Buna göre Cuma günü hangi sınav yapılır?', 'Fizik', ['Matematik sınavı', 'Türkçe sınavı', 'Tarih sınavı'], 'Kimya=Perşembe. Tarih Cuma değilse ve Türkçe\'den hemen sonraysa (Türkçe, Tarih) çifti yalnızca (Pzt, Sal) veya (Sal, Çar) olabilir; her durumda Cuma\'ya kalamazlar. Geriye Matematik ve Fizik kalır; Matematik Fizik\'ten önce olacağından Cuma günü kesinlikle Fizik sınavı yapılır.'),
  ('Bir hastanede dört doktor (Ali, Burcu, Canan, Derya) nöbet değişimi yapmaktadır. "Ali nöbet tutarsa Burcu tutmaz", "Canan nöbet tutmazsa Derya tutar", "Burcu ile Canan aynı gece nöbet tutamaz" kuralları geçerlidir. Belirli bir gece Ali\'nin nöbet tutmadığı ve Derya\'nın da nöbet tutmadığı biliniyorsa aşağıdakilerden hangisi kesinlikle doğrudur?', 'Canan nöbet tutmaktadır ve Burcu tutmamaktadır.', ['Burcu nöbet tutmaktadır ve Canan tutmamaktadır.', 'Hem Burcu hem Canan nöbet tutmaktadır.', 'Ne Burcu ne de Canan nöbet tutmaktadır.'], 'Derya nöbet tutmuyorsa "Canan tutmazsa Derya tutar" kuralının karşıt tersiyle Canan kesinlikle nöbet tutmaktadır. Burcu ile Canan aynı gece tutamadığından Burcu kesinlikle nöbet tutmamaktadır.'),
  ('Bir şifre tablosunda her harfe 1\'den 9\'a kadar farklı bir rakam atanmıştır. "AT" = 17, "TAŞ" = 714 ve "ŞAT" = 417 olduğuna göre "AŞA" kelimesinin kodu nedir?', '141', ['414 kodudur', '747 kodudur', '171 kodudur'], '"AT" = 17 olduğundan A=1, T=7\'dir. "TAŞ" = 714 olduğundan Ş=4 bulunur. "ŞAT" = 417 bu değerleri doğrular. Dolayısıyla "AŞA" = 141 olur.'),
  ('Her katında A ve B olmak üzere iki daire bulunan 3 katlı bir apartmanda 6 kişi (Mert, Nisa, Onur, Pelin, Rıza, Seda) oturmaktadır. Mert 1A\'da, Rıza 1B\'dedir. Seda, Nisa\'nın tam bir kat üstündeki aynı harfli dairededir. Pelin 2B\'de oturduğuna göre Onur hangi dairede oturmaktadır?', '3B', ['2A dairesindedir', '3A dairesindedir', '1B dairesindedir'], '1A=Mert, 1B=Rıza, 2B=Pelin yerleşmiştir. Boş daireler 2A, 3A ve 3B\'dir. Seda, Nisa\'nın tam bir kat üstünde aynı harfli dairede olacaksa tek olası çift Nisa=2A ve Seda=3A\'dır. Boşta kalan tek daire 3B olduğundan Onur 3B\'de oturur.'),
  ('Bir dijital saat 23.48\'i gösterirken pil azaldığı için her 1 gerçek dakikada 50 saniye ilerlemeye başlıyor. Gerçekte 1 saat 12 dakika geçtiğinde bu dijital saat kaçı gösterir?', '00.48', ['01.00 zamanını gösterir', '00.54 zamanını gösterir', '00.42 zamanını gösterir'], 'Gerçekte 1 saat 12 dakika = 72 dakika geçer. Saat her gerçek dakikada 50 saniye (5/6 dakika) ilerlediğinden 72 × (5/6) = 60 dakika (1 saat) ileri gider. 23.48 + 1 saat = 00.48 olur.'),
  ('Dört arkadaş (Ege, Fırat, Gizem, Hale) farklı renkte (siyah, beyaz, gri, lacivert) mont giymiştir. Ege\'nin montu siyah veya beyaz değildir. Fırat\'ın montu gridir. Hale\'nin montu siyah olmadığına göre Gizem\'in montu kesinlikle hangi renktedir?', 'Siyah', ['Beyaz renktedir', 'Lacivert renktedir', 'Gri renktedir'], 'Fırat=Gri olduğuna göre Ege siyah, beyaz ve gri giyemediğinden kesinlikle Lacivert giyer. Geriye siyah ve beyaz kalır; Hale siyah giymediğine göre Hale=Beyaz, Gizem ise kesinlikle Siyah mont giymiştir.'),
  ('Bir fabrikada 3 makine (M1, M2, M3) Pazartesi\'den Cuma\'ya kadar çalışacaktır. Her gün tam 2 makine çalışmalı ve hiçbir makine 3 gün üst üste çalışmamalıdır. M1 makinesi Pazartesi, Salı ve Perşembe günleri çalıştığına göre M1\'in Çarşamba ve Cuma günlerindeki çalışma durumu hakkında ne söylenebilir?', 'Çarşamba çalışmaz, Cuma çalışabilir.', ['Çarşamba çalışır, Cuma çalışamaz.', 'Hem Çarşamba hem Cuma çalışmak zorundadır.', 'Ne Çarşamba ne de Cuma çalışabilir.'], 'M1 Pazartesi ve Salı çalıştığı için 3 gün üst üste çalışmama kuralı gereği Çarşamba kesinlikle çalışamaz. Perşembe çalıştıktan sonra Cuma çalışırsa yalnızca 2 gün üst üste (Per-Cum) çalışmış olur, bu nedenle Cuma çalışabilir.'),
  ('Üç kutudan birinde 2 altın, birinde 2 gümüş, birinde 1 altın 1 gümüş sikke vardır. Kutuların üstündeki "AA", "GG", "AG" etiketlerinin hepsi yanlıştır. "AG" etiketli kutudan rastgele çekilen sikke gümüş ise "AA" etiketli kutuda kesinlikle hangi sikkeler vardır?', '1 altın, 1 gümüş', ['2 gümüş sikke', '2 altın sikke', 'En az 2 altın sikke'], '"AG" etiketli kutu yanlış olduğundan ve içinden gümüş çıktığından bu kutu kesinlikle "GG" (2 gümüş) kutusudur. "AA" etiketli kutuda 2 altın olamaz ve 2 gümüş kullanıldığına göre "AA" etiketli kutuda kesinlikle 1 altın, 1 gümüş bulunur.'),
  ('Altı harflik {A=1, B=2, C=3, Ç=4, D=5, E=6} mini alfabesinde bir şifre makinesi kelimeyi önce ters çevirmekte, sonra her harfi döngüsel olarak 2 sıra ileri kaydırmaktadır (D→A, E→B). Buna göre "BADE" kelimesinin şifresi hangisidir?', 'BACÇ', ['BÇCÇ şifresi', 'ÇCAB şifresi', 'BAÇC şifresi'], '"BADE" ters çevrilince "EDAB" olur. Harfler 2 sıra döngüsel kaydırıldığında E(6)→B(2), D(5)→A(1), A(1)→C(3), B(2)→Ç(4) elde edilir; şifre "BACÇ" olur.'),
  ('Dört arkadaşın (Kaan, Mert, Ozan, Tarık) boyları birbirinden farklıdır. "Mert, Kaan\'dan uzundur", "Ozan en kısa kişi değildir" ve "Tarık yalnızca bir kişiden uzundur" önermelerinin tamamı doğrudur. Buna göre boyu en kısa olan kişi kesinlikle kimdir?', 'Kaan', ['Mert kişisidir', 'Ozan kişisidir', 'Tarık kişisidir'], 'Tarık yalnızca 1 kişiden uzunsa en kısa olamaz (3. sıradadır). Mert Kaan\'dan uzunsa Mert de en kısa olamaz. Ozan\'ın da en kısa olmadığı verildiğine göre boyu en kısa olan kişi kesinlikle Kaan\'dır.'),
  ('Üç basamaklı bir kilit şifresi için şu ipuçları veriliyor: "482" sayısında bir rakam doğru ve yeri doğru; "416" sayısında bir rakam doğru ama yeri yanlış; "204" sayısında iki rakam doğru ama yerleri yanlış; "738" sayısında hiçbir rakam doğru değil. Bu kilit şifresi kaçtır?', '062', ['602 sayısıdır', '042 sayısıdır', '620 sayısıdır'], '7, 3, 8 elenir. "482"de 4 doğru ve yerinde olsaydı "416"da 4\'ün yeri yanlış olamazdı; demek ki 4 yok, 2 doğru ve 3. basamaktadır (_ _ 2). "204"te 4 yok, 2 ve 0 doğru ama yerleri yanlış: 2 zaten 3. basamakta, 0 da 2. basamakta olamayacağından 0 kesinlikle 1. basamaktadır (0 _ 2). "416"da 4 yok; 1 veya 6 doğru ve yeri yanlış. 1 zaten 2. basamakta olduğu için yeri yanlış kalamaz; dolayısıyla 6 doğrudur ve 2. basamağa gelir: 062.'),
  ('Bir bilet gişesinde tek sıra hâlinde bekleyen 18 kişiden Eda baştan 7., Fırat ise sondan 5. sıradadır. Eda ile Fırat kendi aralarında yer değiştirirse Fırat yeni durumda baştan kaçıncı ve sondan kaçıncı olur?', 'Baştan 7., sondan 12.', ['Baştan 14., sondan 5.', 'Baştan 7., sondan 11.', 'Baştan 6., sondan 13.'], 'Fırat, Eda\'nın eski yeri olan baştan 7. sıraya geçer. 18 kişilik sırada baştan 7. olan kişinin arkasında 18 - 7 = 11 kişi bulunduğundan Fırat sondan 11 + 1 = 12. sırada olur.'),
  ('Bir hastanede Pazartesi\'den Cuma\'ya kadar 5 günde K, L, M, N, P birimleri birer gün hizmet vermektedir. K, L\'den hemen önceki gündür. M, N\'den sonraki bir gündür. P Çarşamba, N ise Perşembe günü hizmet verdiğine göre K birimi hangi gündür?', 'Pazartesi', ['Salı günüdür', 'Cuma günüdür', 'Perşembe günüdür'], 'P=Çarşamba, N=Perşembe\'dir. M, N\'den sonra olacağından M kesinlikle Cuma olur. Kalan Pazartesi ve Salı günlerine K, L\'den hemen önce olacak şekilde K=Pazartesi, L=Salı yerleşir.'),
  ('Bir turnuvada 5 takım (A, B, C, D, E) tek devreli lig oynuyor (galibiyet 3, beraberlik 1, mağlubiyet 0). A takımı 4 maçta 8 puan, B takımı 4 maçta 10 puan almıştır. A ile B arasındaki maçın sonucu hakkında ne söylenebilir?', 'Kesinlikle berabere bitmiştir.', ['Kesinlikle B takımı kazanmıştır.', 'Kesinlikle A takımı kazanmıştır.', 'Sonuç kesin olarak belirlenemez.'], '4 maçta 10 puan yalnızca 3G 1B 0M ile, 8 puan ise yalnızca 2G 2B 0M ile alınabilir. Her iki takımın da hiç mağlubiyeti (0M) bulunmadığından aralarındaki maçta ikisi de yenilmemiştir; yani maç kesinlikle berabere bitmiştir.'),
  ('Üç harfli KAR, NAR, RAN ve ANA kelimelerinin rakam kodları sırasız olarak 121, 314, 214 ve 412\'dir. Buna göre "KARA" kelimesinin rakam kodu hangisidir?', '3141', ['2141 sayısıdır', '4131 sayısıdır', '3121 sayısıdır'], 'İlk ve son harfi aynı olan tek kelime ANA\'dır; bu nedenle ANA=121 → A=1, N=2. NAR ve RAN birbirinin tersidir (214 ve 412); N=2 olduğundan NAR=214, RAN=412 → R=4 bulunur. Kalan KAR=314 olduğundan K=3 çıkar. Böylece KARA=3141 olur.'),
  ('Bir raylı sistemde M1 hattı A-B-C-D-E, M2 hattı X-B-Y-D-Z istasyonlarından geçmektedir. M1\'de her durak arası 4 dakika, M2\'de her durak arası 2 dakikadır. Aktarma süresi 3 dakikadır. A istasyonundan Z istasyonuna en kısa sürede gitmek isteyen yolcu hangi istasyonda aktarma yaparak toplam kaç dakikada ulaşır?', 'B\'de aktarma, 13 dakika', ['D\'de aktarma, 17 dakika', 'B\'de aktarma, 15 dakika', 'D\'de aktarma, 14 dakika'], 'B\'de aktarma: A→B (4 dk) + aktarma (3 dk) + B→Y→D→Z (3 × 2 = 6 dk) = 13 dakika. D\'de aktarma: A→B→C→D (12 dk) + aktarma (3 dk) + D→Z (2 dk) = 17 dakika. En kısa yol B aktarmasıyla 13 dakikadır.'),
  ('Dört kapalı kutunun (1, 2, 3, 4) üzerinde sırasıyla "Elma", "Muz", "Kiraz" ve "Üzüm" yazmakta olup tüm etiketler yanlıştır. 1 numaralı kutuda kiraz, 3 numaralı kutuda elma bulunduğu açığa çıkarsa 2 numaralı kutuda kesinlikle hangi meyve vardır?', 'Üzüm', ['Muz meyvesi vardır', 'Kiraz meyvesi vardır', 'Elma meyvesi vardır'], '1=Kiraz ve 3=Elma belirlendiğine göre geriye 2 ("Muz") ve 4 ("Üzüm") numaralı kutular için Muz ve Üzüm kalır. Etiketler yanlış olduğundan 2 numaralı kutuda Muz olamaz; dolayısıyla 2\'de kesinlikle Üzüm, 4\'te Muz vardır.'),
  ('Bir robot (0, 0) noktasından doğuya bakarak başlar ve "İleri 5, Sol, İleri 6, Sol, İleri 2, Sağ, İleri 2" komutlarını uygular. Robotun son konumu başlangıç noktasına göre nerededir?', '3 birim doğu, 8 birim kuzey', ['3 birim batı, 8 birim kuzey', '7 birim doğu, 4 birim kuzey', '3 birim doğu, 4 birim kuzey'], 'Başlangıç (0,0) doğu: İleri 5 → (5,0). Sol (kuzey), İleri 6 → (5,6). Sol (batı), İleri 2 → (3,6). Sağ (kuzey), İleri 2 → (3,8). Son konum 3 birim doğu, 8 birim kuzeydir.'),
  ('Pazartesi\'den Cuma\'ya 5 günde Coğrafya, Tarih, Biyoloji, Kimya ve Fizik sınavları birer gün yapılacaktır. Fizik, Kimya\'dan sonraki bir gündedir. Biyoloji Salı günüdür. Tarih, Coğrafya\'dan hemen önceki gündür ve Pazartesi günü değildir. Buna göre Pazartesi günü hangi sınav kesinlikle yapılır?', 'Kimya', ['Fizik sınavı yapılır', 'Coğrafya sınavı yapılır', 'Tarih sınavı yapılır'], 'Biyoloji=Salı\'dır. Tarih Pazartesi değilse ve Coğrafya\'nın hemen önündeyse (Tarih, Coğrafya) çifti ya (Çar, Per) ya da (Per, Cum) olabilir; Pazartesi\'ye gelemezler. Kalan iki sınav Kimya ve Fizik\'tir; Kimya Fizik\'ten önce olacağından Pazartesi kesinlikle Kimya sınavı yapılır.'),
  ('Bir okulda dört öğrenci (Pelin, Rıza, Sema, Tolga) geziye katılma kararı verecektir. "Pelin katılırsa Rıza katılmaz", "Sema katılmazsa Tolga katılır", "Rıza ile Sema aynı anda katılamaz" kuralları geçerlidir. Tolga\'nın geziye katılmadığı biliniyorsa aşağıdakilerden hangisi kesinlikle doğrudur?', 'Sema katılır ve Rıza katılmaz.', ['Rıza katılır ve Sema katılmaz.', 'Pelin katılır ve Tolga katılır.', 'Hem Pelin hem Rıza katılır.'], 'Tolga katılmıyorsa "Sema katılmazsa Tolga katılır" kuralının karşıt tersiyle Sema kesinlikle katılır. Rıza ile Sema aynı anda katılamayacağından Rıza kesinlikle katılmaz (Pelin\'in durumu belirsiz kalır).'),
  ('Bir harf-rakam şifresinde "SOL" = 381, "LOS" = 183 ve "KOL" = 581 olarak kodlanmıştır. Buna göre "OKS" kelimesinin kodu nedir?', '853', ['835 sayısıdır', '583 sayısıdır', '358 sayısıdır'], 'SOL=381 ve LOS=183 karşılaştırmasından S=3, O=8, L=1 çıkar. KOL=581 olduğundan K=5 bulunur. Böylece O(8)-K(5)-S(3) = 853 olur.'),
  ('Her katında 1 ve 2 numaralı iki daire bulunan 3 katlı bir apartmanda 6 kişi (A, B, C, D, E, F) oturmaktadır. A 3-1\'de, B 3-2\'dedir. C, D\'nin tam bir kat altında ve aynı numaralı dairededir. E 1-2 dairesinde oturduğuna göre F hangi dairededir?', '2-2', ['1-1 dairesindedir', '2-1 dairesindedir', '3-1 dairesindedir'], '3-1(A), 3-2(B) ve 1-2(E) doludur. Boş daireler 1-1, 2-1 ve 2-2\'dir. C, D\'nin tam bir kat altında aynı numarada olacağından tek uygun ikili C=1-1 ve D=2-1\'dir. Boş kalan 2-2 dairesinde kesinlikle F oturur.'),
  ('Gerçek saat 12.00\'de doğru ayarlanan bir duvar saati her 1 gerçek saatte 5 dakika geri kalmaktadır. Gerçek saat 20.00\'yi gösterdiğinde bu duvar saati kaçı gösterir?', '19.20', ['19.15 saatini gösterir', '19.30 saatini gösterir', '19.25 saatini gösterir'], '12.00\'den 20.00\'ye 8 gerçek saat geçer. Her saatte 5 dakika geri kaldığından toplam 8 × 5 = 40 dakika geri kalır. 20.00 - 40 dakika = 19.20 gösterir.'),
  ('Dört arkadaş (Cem, Duru, Efe, Filiz) farklı içecekler (çay, kahve, limonata, ayran) sipariş etmiştir. Cem kahve veya ayran içmemektedir. Duru limonata içmektedir. Filiz ayran içmediğine göre Efe kesinlikle hangi içeceği sipariş etmiştir?', 'Ayran', ['Kahve sipariş etmiştir', 'Çay sipariş etmiştir', 'Limonata sipariş etmiştir'], 'Duru=Limonata\'dır. Cem kahve, ayran ve limonata içemediğinden kesinlikle Çay içer. Kalan kahve ve ayrandan Filiz ayran içmiyorsa Filiz=Kahve, Efe ise kesinlikle Ayran sipariş etmiştir.'),
  ('Bir spor salonunda 3 antrenör (T1, T2, T3) Pazartesi\'den Cuma\'ya kadar çalışacaktır. Her gün 2 antrenör görevli olup hiçbir antrenör 3 gün üst üste çalışamaz. T2 antrenörü Pazartesi, Çarşamba ve Perşembe günleri görevli olduğuna göre T2\'nin Salı ve Cuma günlerindeki çalışma durumu için ne söylenebilir?', 'Ne Salı ne de Cuma çalışabilir.', ['Salı çalışabilir, Cuma çalışamaz.', 'Salı çalışamaz, Cuma çalışabilir.', 'Hem Salı hem Cuma çalışmak zorundadır.'], 'T2 Salı çalışırsa Pazartesi-Salı-Çarşamba üç gün üst üste çalışmış olur (yasak). Cuma çalışırsa Çarşamba-Perşembe-Cuma üç gün üst üste çalışmış olur (yasak). Dolayısıyla T2 ne Salı ne de Cuma çalışabilir.'),
  ('Üç kutudan birinde 2 kırmızı, birinde 2 mavi, birinde 1 kırmızı 1 mavi kalem vardır. Kutuların üstündeki "KK", "MM", "KM" etiketlerinin hepsi yanlıştır. "KM" etiketli kutudan rastgele çekilen kalem kırmızı ise "MM" etiketli kutuda kesinlikle hangi kalemler vardır?', '1 kırmızı, 1 mavi', ['2 kırmızı kalem', '2 mavi kalem', 'En az 2 mavi kalem'], '"KM" etiketli kutu yanlış olduğundan ve içinden kırmızı çıktığından kesinlikle "KK" (2 kırmızı) kutusudur. "MM" etiketinde 2 mavi olamayacağına ve 2 kırmızı kullanıldığına göre "MM" etiketli kutuda kesinlikle 1 kırmızı, 1 mavi bulunur.'),
  ('Bir takvim yılının 20 Haziran günü Pazartesi ise aynı yılın 20 Ağustos günü hangi güne denk gelir?', 'Cumartesi', ['Cuma günüdür', 'Pazar günüdür', 'Salı günüdür'], 'Haziran 30, Temmuz 31 gündür. 20 Haziran\'dan 20 Ağustos\'a 30 + 31 = 61 gün geçer. 61\'in 7 ile bölümünden kalan 5 olduğundan Pazartesi + 5 gün = Cumartesi olur.'),
  ('Dört katlı (1-4) bir otoparkta kırmızı, mavi, sarı ve beyaz araçlar farklı katlardadır. Kırmızı araç 1. katta değildir ve sarı aracın hemen üstündeki kattadır. Beyaz araç 4. katta olduğuna göre mavi araç kaçıncı katlarda bulunabilir?', '1 veya 3', ['Yalnızca 1. katta', 'Yalnızca 2. katta', '2 veya 4. katta'], 'Beyaz=4\'tür. Kırmızı, sarının hemen üstünde olacağından (Sarı, Kırmızı) ikilisi (1, 2) veya (2, 3) olabilir. İlk durumda Mavi=3, ikinci durumda Mavi=1 olur. Yani Mavi 1 veya 3. katta bulunabilir.'),
  ('Üç basamaklı bir şifre için şu ipuçları verilmiştir: "614" sayısında bir rakam doğru ve yeri doğru; "682" sayısında bir rakam doğru ama yeri yanlış; "206" sayısında iki rakam doğru ama ikisinin de yeri yanlış; "738" sayısında hiçbir rakam doğru değil. Bu şifre kaçtır?', '024', ['042 sayısıdır', '420 sayısıdır', '204 sayısıdır'], '7, 3, 8 elenir. "614" ve "682" birlikte incelendiğinde 6 doğru olsaydı aynı 1. basamakta hem yeri doğru hem yeri yanlış olamazdı; dolayısıyla 6 yoktur. "206"da 2 (1. basamakta yanlış) ve "682"de 2 (3. basamakta yanlış) olduğundan 2 kesinlikle 2. basamaktadır (_ 2 _). "206"da 0 (2. basamakta yanlış) olduğundan 0 ya 1. ya 3. basamaktadır. "614"ten 1 (2. basamakta 2 var) olamayacağından 4 kesinlikle 3. basamaktadır (_ 2 4). Geriye 0 için 1. basamak kalır: 024.'),
  ('Bir yürüyüşte başlangıç noktasından 700 m kuzeye, 200 m batıya, 100 m güneye ve 1000 m doğuya yürüyen bir kişinin başlangıç noktasına kuş uçuşu mesafesi kaç metredir?', '1000', ['1200 metredir', '1400 metredir', '800 metredir'], 'Dikey yer değiştirme: 700 - 100 = 600 m kuzey. Yatay yer değiştirme: 1000 - 200 = 800 m doğu. 6-8-10 özel dik üçgeninden kuş uçuşu mesafe 1000 metredir.'),
  ('Bir şifre sisteminde dört basamaklı bir sayının her rakamı 9\'dan çıkarılmakta (0↔9, 1↔8, ...), ardından sayının tüm rakamları ters sıraya çevrilmektedir. Buna göre "1538" sayısının şifrelenmiş hâli nedir?', '1648', ['8461 sayısıdır', '1468 sayısıdır', '8641 sayısıdır'], 'Her rakam 9\'dan çıkarılınca 1→8, 5→4, 3→6, 8→1 (8461) elde edilir. Rakamlar ters sıraya çevrilince 1648 bulunur.'),
  ('Bir okulda 50 dakikalık dersler arasında 10 dakikalık teneffüsler vardır. İlk ders saat 08.30\'da başladığına göre 4. ders saat kaçta biter?', '12.20', ['12.30 saatinde biter', '12.10 saatinde biter', '12.00 saatinde biter'], '4 ders toplam 4 × 50 = 200 dakika, aralarında 3 teneffüs toplam 3 × 10 = 30 dakika sürer. Toplam süre 230 dakika = 3 saat 50 dakikadır. 08.30 + 3 saat 50 dakika = 12.20 olur.'),
  ('Bir masa tenisi grubunda 4 oyuncu (A, B, C, D) tek devreli lig oynuyor (beraberlik yok, galibiyet 1 puan). Turnuva sonunda A=2, B=2, C=2 puan aldığına göre D kaç puan almıştır?', '0', ['1 puan almıştır', '2 puan almıştır', '3 puan almıştır'], '4 oyuncu toplam (4 × 3) / 2 = 6 maç yapar ve her maç 1 puan üretir (toplam 6 puan). A, B, C toplam 2 + 2 + 2 = 6 puan aldığından D\'ye 6 - 6 = 0 puan kalır.'),
];
